עב. הַשֵּׁם יִתְבָּרַךְ בָּרָא אֶת הָעוֹלָם בְּגוּף וָנֶפֶשׁ, חֹמֶר וְצוּרָה, וְכַוָּנָתוֹ הָיָה כְּדֵי לְהַכְנִיעַ הַגּוּף לְגַבֵּי הַנֶּפֶשׁ, וְזֶה עִקַּר עֲבוֹדָתֵנוּ. וּכְמוֹ שֶׁבִּפְרָטִיּוּת צָרִיךְ כָּל אָדָם לְהִתְגַּבֵּר לְבַטֵּל הַגּוּף לְגַבֵּי הַנֶּפֶשׁ, שֶׁכָּל פְּעֻלּוֹת הַגּוּף יִהְיֶה רַק בִּשְׁבִיל הַנֶּפֶשׁ, הַיְנוּ לַעֲשׂוֹת רְצוֹנוֹ יִתְבָּרַךְ, שֶׁזֶּה תְּשׁוּקַת הַנֶּפֶשׁ; כְּמוֹ־כֵן בִּכְלָלִיּוּת הָעוֹלָם, יִשְׂרָאֵל עַם קָדוֹשׁ הֵם בְּחִינַת הַנֶּפֶשׁ וְהַנְּשָׁמָה שֶׁל כָּל הָעוֹלָם, וְכָל אֻמִּין דְּעָלְמָא וְכָל הַבְּרוּאִים כֻּלָּם הֵם בְּחִינַת גּוּף כְּנֶגֶד יִשְׂרָאֵל, וְכֻלָּם צְרִיכִים לִהְיוֹת נִכְנָעִים וּבְטֵלִים לְגַבֵּי הַנֶּפֶשׁ שֶׁהֵם יִשְׂרָאֵל וְלַעֲשׂוֹת רְצוֹנָם, כִּי אֵין לָהֶם שׁוּם קִיּוּם וְחַיּוּת בְּלֹא יִשְׂרָאֵל, כְּמוֹ שֶׁאֵין חַיּוּת לַגּוּף בְּלֹא הַנְּשָׁמָה. וְעִקַּר הַתַּכְלִית שֶׁל כָּל הַבְּרִיאָה כֻּלָּהּ בִּכְלָל וּבִפְרָט הוּא, שֶׁיִּתְבַּטֵּל הַחֹמֶר וְהַגּוּף לְגַבֵּי הַנְּשָׁמָה, לְהַפְשִׁיט כָּל דָּבָר מִגַּשְׁמִיּוּתוֹ וּמֵחָמְרִיּוּתוֹ, לַהֲפֹךְ מֵחֹמֶר לְצוּרָה, מִגּוּף לְנֶפֶשׁ, כְּדֵי שֶׁיַּעֲלֶה וְיִכָּלֵל וְיִתְדַּבֵּק בְּשָׁרְשׁוֹ וְיָשׁוּב לִמְקוֹר חוֹצְבוֹ שֶׁבַּקְּדֻשָּׁה, מְקוֹם אֲשֶׁר הָיָה שָׁם אָהֳלֹה בַּתְּחִלָּה קֹדֶם שֶׁנִּבְרָא, וְזֶה עִקַּר עֲבוֹדַת הָאָדָם בָּעוֹלָם הַזֶּה, וְזֶה כְּלַל כָּל הַתּוֹרָה וְהַמִּצְוָה, כִּי הַשֵּׁם יִתְבָּרַךְ שִׁעֵר בְּדַעְתּוֹ שֶׁעַל־יְדֵי מִצְו?ֹת אֵלּוּ נוּכַל לְהַכִּיר אוֹתוֹ יִתְבָּרַךְ. וּצְרִיכִין דַּיְקָא לַעֲשׂוֹת הַמִּצְוָה בְּפֹעַל בְּעֻבְדָּא דַיְקָא, כִּי כָּךְ שִׁעֵר הַשֵּׁם יִתְבָּרַךְ, שֶׁעַל־יְדֵי עֲשִׂיַּת הַמִּצְו?ֹת הָאֵלּוּ בְּמַעֲשֶׂה דַיְקָא, עַל־יְדֵי־זֶה אָנוּ יְכוֹלִין לְזַכֵּךְ גַּשְׁמִיּוּת גּוּפֵנוּ וְגַשְׁמִיּוּת כָּל הָעוֹלָם, עַד שֶׁיִּתְהַפֵּךְ מֵחֹמֶר לְצוּרָה בִּכְלָל וּבִפְרָט, כְּדֵי שֶׁיַּעֲלוּ וְיִכָּלְלוּ כָּל הַדְּבָרִים בְּשָׁרְשָׁן כַּנַּ"ל, דְּהַיְנוּ לָדַעַת וּלְהַכִּיר אוֹתוֹ יִתְבָּרַךְ, שֶׁזֶּהוּ תַּכְלִית שֶׁל כָּל הַבְּרִיאָה כֻּלָּהּ, שֶׁהוּא בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ. וְעַל־כֵּן אֱמוּנָה הוּא יְסוֹד כָּל הַתּוֹרָה, כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל: בָּא חֲבַקּוּק וְהֶעֱמִידוֹ עַל אֱמוּנָה, כִּי זֶה עִקַּר הַתַּכְלִית שֶׁל כָּל הַבְּרִיאָה, לִזְכּוֹת לֶאֱמוּנָה, לְהַאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ בָּרָא הַכֹּל בַּעֲשָׂרָה מַאֲמָרוֹת, וְהוּא יִתְבָּרַךְ מְחַיֶּה אֶת כֻּלָּם, שֶׁעַל־יְדֵי־זֶה שֶׁמַּאֲמִינִים שֶׁכָּל הַחַיּוּת הוּא רַק מֵהַשֵּׁם יִתְבָּרַךְ לְבַד, עַל־יְדֵי־זֶה מַעֲלִין וּמְרִימִין כָּל הַדְּבָרִים לְהַשֵּׁם יִתְבָּרַךְ. וְעַל־כֵּן אֵין שׁוּם דָּבָר עוֹמֵד בִּפְנֵי פִּקּוּחַ־נֶפֶשׁ מִיִּשְׂרָאֵל, חוּץ מֵעֲבוֹדָה זָרָה וְגִלּוּי־עֲרָיוֹת וּשְׁפִיכוּת־דָּמִים, כִּי כָּל נֶפֶשׁ מִיִּשְׂרָאֵל כְּלוּלָה מֵרְמַ"ח אֵיבָרִים וּשְׁסָ"ה גִּידִים, שֶׁהֵם בְּחִינַת כְּלַל כָּל הַתּוֹרָה כֻּלָּהּ, רְמַ"ח מִצְו?ֹת עֲשֵׂה וּשְׁסָ"ה מִצְו?ֹת לֹאשׂ תַעֲשֶׂה; וְכָל זְמַן שֶׁמִּתְקַיֵּם בָּעוֹלָם הַזֶּה עוֹד נֶפֶשׁ אֶחָד מִיִּשְׂרָאֵל בְּיוֹתֵר, עַל־יְדֵי־זֶה מִתְגַּבֵּר בְּיוֹתֵר הַנְּשָׁמָה עַל הַגּוּף, כִּי יִשְׂרָאֵל הֵם בְּחִינַת נֶפֶשׁ וְצוּרָה נֶגֶד כְּלַל הָעוֹלָם כַּנַּ"ל, וְכָל מִצְוָה הוּא רַק בְּחִינַת פְּרָט אֶחָד, שֶׁעַל־יְדֵי־ זֶה נִכְלָל אֵיזֶה חֵלֶק וּבְחִינָה מֵהָעוֹלָם בְּשָׁרְשׁוֹ, אֲבָל נֶפֶשׁ מִיִּשְׂרָאֵל הִיא כְּלָלִיּוּת כָּל הַתּוֹרָה כֻּלָּהּ, וְהוּא בְּעַצְמוֹ בְּחִינַת נֶפֶשׁ שֶׁל כָּל הָעוֹלָם כֻּלּוֹ, וְעַל־כֵּן כָּל מִצְו?ֹת הַתּוֹרָה נִדְחִין מִפְּנֵי פִּקּוּחַ־נֶפֶשׁ. אַךְ כָּל זֶה כְּשֶׁנִּשְׁאָר הָאֱמוּנָה בִּשְׁלֵמוּת, שֶׁאָז אַף־עַל־ פִּי שֶׁמֻּכְרָח לַעֲבֹר עַל אֵיזֶה מִצְוָה, חַס וְשָׁלוֹם, מִפְּנֵי פִּקּוּחַ־נֶפֶשׁ, עֲדַיִן הוּא מְקֻשָּׁר בְּהַשֵּׁם יִתְבָּרַךְ עַל־יְדֵי אֱמוּנָה לְבַד, וְיָכוֹל לִחְיוֹת בְּעַצְמוֹ וּלְהָרִים וּלְהַגְבִּיהַּ אֶת כָּל הָעוֹלָם כֻּלּוֹ לְהַשֵּׁם יִתְבָּרַךְ עַל־יְדֵי אֱמוּנָתוֹ לְבַד, שֶׁמַּאֲמִין שֶׁהַשֵּׁם יִתְבָּרַךְ בָּרָא אֶת כָּל הָעוֹלָם בַּעֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶן נֶעְלָמִין הָעֲשֶׂרֶת הַדִּבְּרוֹת שֶׁהֵם כְּלַל כָּל הַתּוֹרָה, שֶׁזֶּה הָיָה הַחַיּוּת וְהַקִּיּוּם שֶׁל הָעוֹלָם קֹדֶם מַתַּן־תּוֹרָה. וְעַל־כֵּן גַּם עַכְשָׁו, כְּשֶׁצְּרִיכִין, חַס וְשָׁלוֹם, לַעֲבֹר עַל מִצְו?ֹת הַתּוֹרָה בִּשְׁבִיל פִּקּוּחַ־נֶפֶשׁ, הוּא בְּחִינַת 'בִּטּוּלָהּ שֶׁל תּוֹרָה זֶהוּ קִיּוּמָהּ', וּכְמַאֲמַר רַבּוֹתֵינוּ זַ"ל: חַלֵּל עָלָיו שַׁבָּת אֶחָד בִּשְׁבִיל שֶׁיִּשְׁמֹר שַׁבָּתוֹת הַרְבֵּה, שֶׁאָז בִּשְׁעַת בִּטּוּלָהּ שֶׁל תּוֹרָה, מְקַבְּלִין חַיּוּת מֵהַתּוֹרָה הַנֶּעְלֶמֶת הַנַּ"ל, שֶׁזֶּה הָיָה קִיּוּם הָעוֹלָם קֹדֶם מַתַּן־תּוֹרָה. אֲבָל כְּשֶׁרוֹצִין שֶׁיַּעֲבֹד עֲבוֹדָה זָרָה, חָלִילָה, אֲזַי בְּוַדַּאי צָרִיךְ שֶׁיֵּהָרֵג וְאַל יַעֲבֹר, כִּי תֵּכֶף כְּשֶׁפּוֹגֵם, חַס וְשָׁלוֹם, בֶּאֱמוּנָה, שׁוּב אֵין לוֹ שׁוּם חַיּוּת כְּלָל וְנֶעֱקָר מִשָּׁרְשׁוֹ לְגַמְרֵי וּמַחֲרִיב כָּל הָעוֹלָם כֻּלּוֹ וְכֹל אֲשֶׁר בּוֹ, אֲשֶׁר כֻּלָּם תְּלוּיִים בּוֹ, שֶׁיֶּשׁ לוֹ כֹחַ לְהַגְבִּיהַּ כֻּלָּם וּלְהַעֲלוֹתָם לְשָׁרְשָׁם הָאֲמִתִּי עַל־יְדֵי הָאֱמוּנָה שֶׁמַּאֲמִין בּוֹ יִתְבָּרַךְ שֶׁבָּרָא אֶת כֻּלָּם כַּנַּ"ל. וּכְשֶׁפּוֹגֵם בֶּאֱמוּנָה, חַס וְשָׁלוֹם, אֲזַי נֶעֱקָר לְגַמְרֵי מִשֹּׁרֶשׁ חַיּוּתוֹ, וּבְוַדַּאי אֵין צְרִיכִין אוֹתוֹ עוֹד בָּעוֹלָם כְּלָל, כִּי לֹא דַי שֶׁאֵינוֹ יָכוֹל לְקַיֵּם אֶת הָעוֹלָם, אַדְּרַבָּה הוּא מַחֲרִיב לְגַמְרֵי אֶת הָעוֹלָם, שֶׁחַיּוּת וְקִיּוּם כָּל הָעוֹלָם הוּא רַק עַל־יְדֵי אֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר: "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה". וְכֵן עַל שְׁפִיכוּת־דָּמִים גַּם־כֵּן יֵהָרֵג וְאַל יַעֲבֹר, כִּי אֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל עַל־יְדֵי חֹזֶק אֱמוּנָתוֹ לְבַד, הוּא בְּחִינַת הַנֶּפֶשׁ וְהַחַיּוּת שֶׁל כָּל הָעוֹלָם, וְעַל־כֵּן כָּל זְמַן שֶׁשֵּׁם יִשְׂרָאֵל נִקְרָא עָלָיו, דְּהַיְנוּ שֶׁיֶּשׁ לוֹ אֱמוּנָה בְּהַשֵּׁם יִתְבָּרַךְ, אָנוּ צְרִיכִין אוֹתוֹ שֶׁיִּתְקַיֵּם בָּעוֹלָם, וְאֵין דּוֹחִין אוֹתוֹ לְהָרְגוֹ מִפְּנֵי חֲבֵרוֹ, אֲפִלּוּ אִם הוּא גָּדוֹל מִמֶּנּוּ הַרְבֵּה, כִּי מִי יוֹדֵעַ גֹּדֶל כֹּחוֹ שֶׁל זֶה בְּעִנְיַן חִזּוּק הָאֱמוּנָה; כְּמוֹ שֶׁאָנוּ רוֹאִים בְּחוּשׁ, שֶׁלִּפְעָמִים הַקַּל שֶׁבַּקַּלִּים מוֹסֵר נַפְשׁוֹ עַל קְדֻשַּׁת הַשֵּׁם יוֹתֵר מִגָּדוֹל שֶׁבְּיִשְׂרָאֵל, וְעַל־ כֵּן אֵין דּוֹחִין נֶפֶשׁ מִפְּנֵי נֶפֶשׁ לְעוֹלָם, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל, כָּל זְמַן שֶׁיֶּשׁ לוֹ אֱמוּנָה, צְרִיכִין אוֹתוֹ שֶׁיִּתְקַיֵּם בָּעוֹלָם, כִּי כָּל אֶחָד מִיִּשְׂרָאֵל מַכְרִיעַ כָּל הָעוֹלָם כֻּלּוֹ לְהַשֵּׁם יִתְבָּרַךְ לְפִי בְּחִינָתוֹ עַל־יְדֵי אֱמוּנָתוֹ לְבַד, וְאִי אֶפְשָׁר לָנוּ לְהַעֲרִיךְ בֵּין נֶפֶשׁ לְנֶפֶשׁ, כִּי מִי יוֹדֵעַ הַכֹּחַ שֶׁל כָּל אֶחָד בְּשֹׁרֶשׁ אֱמוּנָתוֹ. וְעַל־כֵּן מִי שֶׁהוּא אֶפִּיקוֹרוֹס וְאֵין לוֹ אֱמוּנָה, הוּא מֵאֵלּוּ שֶׁמּוֹרִידִין וְלֹא מַעֲלִין, כִּי עִקַּר יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ וְחַיּוּת כָּל הָעוֹלָמוֹת כֻּלָּם הוּא רַק עַל־יְדֵי אֱמוּנָה כַּנַּ"ל. וְעַל־כֵּן בִּשְׁבִיל גִּלּוּי־עֲרָיוֹת גַּם־כֵּן יֵהָרֵג וְאַל יַעֲבֹר, כִּי שְׁמִירַת הַבְּרִית הוּא גַּם־כֵּן יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, וְעִקַּר קִיּוּם הָאֱמוּנָה תָּלוּי בִּשְׁמִירַת הַבְּרִית. וְהַפּוֹגֵם בָּזֶה, הוּא גַּם־כֵּן כְּאִלּוּ עוֹקֵר חַיּוּת כָּל הַנְּפָשׁוֹת וְחַיּוּת כָּל הָעוֹלָם מִשָּׁרְשׁוֹ, וּמַגְבִּיר הַגּוּף עַל הַנֶּפֶשׁ, הַחֹמֶר עַל הַצּוּרָה, שֶׁזֶּה בְּעַצְמוֹ בְּחִינַת פְּגַם עֲבוֹדָה זָרָה. וְעַל־כֵּן אָמְרוּ רַבּוֹתֵינוּ זַ"ל שֶׁפְּגַם הַבְּרִית הוּא בְּחִינַת "אַל תִּפְנוּ אֶל הָאֱלִילִים", וְעַל־כֵּן מְחֻיָּב לִמְסֹר נַפְשׁוֹ וְחַיּוּתוֹ שֶׁלֹּא לַעֲבֹר עַל זֶה, חַס וְשָׁלוֹם (הלכות עבודה זרה הלכה ב, עיין פנים; ועיין יראה ועבודה, אותיות סב סג). 
עג. עַל־יְדֵי אֱמוּנָה שֶׁאָנוּ מַאֲמִינִים בּוֹ יִתְבָּרַךְ שֶׁבָּרָא הַכֹּל, וְכָל הַזְּמַן וְהַמָּקוֹם נִמְשָׁךְ מִמֶּנּוּ יִתְבָּרַךְ, מִבְּחִינַת לְמַעְלָה מֵהַזְּמַן וְהַמָּקוֹם, עַל־יְדֵי־זֶה אָנוּ מְקַשְּׁרִין וּמַעֲלִין הַמָּקוֹם וְהַזְּמַן לִבְחִינַת לְמַעְלָה מֵהַזְּמַן וְהַמָּקוֹם, וְאָז כָּל הַבְּרִיאָה כֻּלָּהּ בִּבְחִינַת לְמַעְלָה מֵהַזְּמַן וְהַמָּקוֹם, שֶׁהוּא בְּחִינַת הַשְׁגָּחָה, שֶׁזֶּה כְּלַל עֲבוֹדַת יִשְׂרָאֵל לְהַעֲלוֹת וּלְקַשֵּׁר וְלִכְלֹל כָּל הַבְּרִיאָה בִּבְחִינַת קֹדֶם הַבְּרִיאָה כַּמְבֹאָר בִּפְנִים (הל' ריבית, הל' ג,

). 
עט. בְּהַתּוֹרָה יֵשׁ חֻקִּים וּמִשְׁפָּטִים, וְעַל יְדֵי שֶׁמְּקַיְּמִין הַמִּשְׁפָּטִים שֶׁבַּתּוֹרָה, שֶׁהֵם אֵלּוּ הַמִּצְו?ֹת שֶׁיֵּשׁ בָּהֶם טַעַם וָשֵׂכֶל, עַל־יְדֵי־ זֶה מְבַטְּלִין כָּל הַקֻּשְׁיוֹת וְהַכְּפִירוֹת הַבָּאִים מֵהַקְּלִפּוֹת שֶׁנִּתְהַוּוּ מִבְּחִינַת שְׁבִירַת כֵּלִים, שֶׁשָּׁם יֵשׁ מְעַט שֵׂכֶל וְאוֹתִיּוֹת, אֲבָל יֵשׁ קֻשְׁיוֹת וּכְפִירוֹת כָּאֵלּוּ שֶׁאִי אֶפְשָׁר לִמְצֹא עֲלֵיהֶם שׁוּם תְּשׁוּבָה עַל־פִּי שֵׂכֶל לְיַשְּׁבוֹ, וְהֵם נִמְשָׁכִין מִבְּחִינַת חָלָל הַפָּנוּי, כַּמְבֹאָר בִּפְנִים. וְאֵלּוּ הַקֻּשְׁיוֹת מִתְבַּטְּלִין עַל־יְדֵי הַחֻקִּים שֶׁבַּתּוֹרָה, שֶׁהֵם הַמִּצְו?ֹת שֶׁאִי אֶפְשָׁר לָנוּ לְהָבִין וּלְהַשִּׂיג בָּהֶם שׁוּם טַעַם וָשֵׂכֶל כְּלָל, וְאָנוּ מְקַיְּמִין אוֹתָם רַק בֶּאֱמוּנָה לְבָד. וְעַל־יְדֵי כֹּחַ אֵלּוּ הַמִּצְו?ֹת נִתְחַזֵּק הָאֱמוּנָה אֶצְלֵנוּ לְגָרֵשׁ וּלְבַטֵּל וּלְבַעֵר מֵאִתָּנוּ כָּל הַקֻּשְׁיוֹת וְאֶפִּיקוֹרְסוּת הַנִּמְשָׁךְ מֵחָלָל הַפָּנוּי, שֶׁשָּׁם אִי אֶפְשָׁר לְהַשִּׂיג שׁוּם שֵׂכֶל וְחָכְמָה כְּלָל, רַק צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה לְבָד. וְזֶה בְּחִינַת אִסּוּר מְעוֹנֵן וּמְנַחֵשׁ וּמְכַשֵּׁף, זֶה בְּחִינַת הַרְחָקַת הַכְּפִירוֹת הַבָּאִים מִשְּׁבִירַת כֵּלִים, שֶׁמִּשָּׁם נִמְשָׁכִין כָּל הַחָכְמוֹת שֶׁל הַמְנַחֲשִׁים וּמְעוֹנְנִים וּמְכַשְּׁפִים. וְאִסּוּר חֻקּוֹת הָעַכּוּ"ם שֶׁלֹּא לָלֶכֶת בְּחֻקּוֹתֵיהֶם הוּא לְרַחֵק כָּל הַכְּפִירוֹת וְהָאֶפִּיקוֹרְסוּת הַבָּאִים מִבְּחִינַת חָלָל הַפָּנוּי; כִּי הַשֵּׁם יִתְבָּרַךְ בְּרַחֲמָיו הִבְדִּילָנוּ מִכָּל הַתּוֹעִים הָאֵלֶּה, וְנָתַן לָנוּ אֶת הַתּוֹרָה שֶׁיְּסוֹדָהּ אֱמוּנָה, וְקִדְּשָׁנוּ בְּמִצְו?ֹתָיו הַקְּדוֹשִׁים שֶׁיֵּשׁ בָּהֶם חֻקִּים וּמִשְׁפָּטִים, שֶׁעַל־יְדֵי־זֶה אָנוּ מְבַטְּלִין וּמְגָרְשִׁין שְׁנֵי מִינֵי אֶפִּיקוֹרְסוּת וְקֻשְׁיוֹת הַנַּ"ל וְזוֹכִין לֶאֱמוּנָה שְׁלֵמָה (הלכות חוקות העמים, הל' ג). 
פ. כָּל הַהַשָּׂגוֹת וְכָל הַצִּמְצוּמִים דִּקְדֻשָּׁה שֶׁזּוֹכִין עַל־יָדָם לְהַשִּׂיג אֱלָקוּת, כֻּלָּם הֵם בְּחִינַת אֱמוּנָה שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, כְּמוֹ שֶׁנֶּאֱמַר: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", וּכְתִיב: "צַדִּיק בֶּאֱמוּנָתוֹ יִחְיֶה". כִּי אֲנָשִׁים פְּשׁוּטִים וּקְטַנֵּי הָעֵרֶךְ, בְּוַדַּאי עִקַּר חַיּוּתָם וְתִקְוָתָם לִזְכּוֹת לְתַכְלִית הַנִּצְחִי הָאֲמִתִּי הוּא רַק עַל־יְדֵי אֱמוּנָה. אַךְ אֲפִלּוּ מִי שֶׁיֶּשׁ לוֹ שֵׂכֶל גָּדוֹל וְהוּא לַמְדָן וְחָרִיף גָּדוֹל בְּשַׁ"ס וּפוֹסְקִים, וַאֲפִלּוּ אִם יֶשׁ לוֹ יָד גַּם בְּחָכְמַת הַקַּבָּלָה, בַּזֹּהַר הַקָּדוֹשׁ וּבְכִתְבֵי הָאֲרִ"י זַ"ל - כָּל זְמַן שֶׁלֹּא זִכֵּךְ עַצְמוֹ מִזֻּהֲמַת הַנָּחָשׁ וְלֹא שִׁבֵּר עֲדַיִן לְגַמְרֵי תַּאֲוַת גּוּפוֹ וְחָמְרוֹ, וְיֶשׁ לוֹ עֲדַיִן אֵיזֶה אֲחִיזָה וְשֶׁמֶץ דָּבָר מִתַּאֲוַת הַגּוּף וְהַבְלֵי עוֹלָם הַזֶּה, בְּוַדַּאי עֲדַיִן אֵין שִׂכְלוֹ שָׁלֵם, וְאָסוּר לוֹ לִכְנֹס בְּשִׂכְלוֹ בְּחָכְמַת הַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ, כִּי יוּכַל לְהִכָּשֵׁל וְלִפֹּל, חַס וְשָׁלוֹם, רַחֲמָנָא לִצְּלַן. וְעַל־כֵּן צָרִיךְ לְהִתְחַזֵּק רַק בֶּאֱמוּנָה וּלְהַשְׁלִיךְ שִׂכְלוֹ לְגַמְרֵי, וְלִסְמֹךְ עַל אֲבוֹתֵינוּ הַקְּדוֹשִׁים וְעַל הַצַּדִּיקִים אֲמִתִּיִּים אֲשֶׁר כָּפוּ אֶת יִצְרָם וְשָׁבְרוּ אֶת הַחֹמֶר לְגַמְרֵי, כִּי רַק הֵם זָכוּ לְהַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ בְּתַכְלִית הַשְּׁלֵמוּת. וְאַף־עַל־פִּי־כֵן, אֲפִלּוּ צַדִּיקִים כָּאֵלּוּ, שֶׁטִּהֲרוּ וְקִדְּשׁוּ עַצְמָן מִזֻּהֲמַת הַנָּחָשׁ לְגַמְרֵי וְשָׁבְרוּ כָּל הַתַּאֲווֹת וּבִטְּלוּ אֶת הַגּוּף וְהַחֹמֶר לְגַמְרֵי, גַּם הֵם הָיָה עִקַּר הִתְחַזְּקוּת שֶׁלָּהֶם רַק עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה. כִּי אִי אֶפְשָׁר לְהַשִּׂיג שׁוּם הַשָּׂגָה וְלָדַעַת שׁוּם יְדִיעָה אֲמִתִּית בְּהִתְנוֹצְצוּת אֱלָקוּתוֹ יִתְבָּרַךְ, כִּי־אִם עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה, אֲשֶׁר הִיא הַשַּׁעַר שֶׁדֶּרֶךְ שָׁם נִכְנָסִין לְכָל הַקְּדֻשּׁוֹת וּלְכָל הַהַשָּׂגוֹת וּלְכָל הַיְדִיעוֹת הַקְּדוֹשִׁים, בִּבְחִינַת "בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ" - "זֹאת" הוּא בְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה, שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ, בְּחִינַת "זֹאת הַתּוֹרָה וְכוּ'", "זֹאת" דַּיְקָא. וְזֶה שֶׁהֶאֱרִיךְ בַּתִּקּוּנִים: דְּלֵית רְשׁוּ לְנָבִיא וְחוֹזֶה לְאַעֲלָא לְקֻדְשָׁא בַּר מִנָּהּ וְכוּ'. כִּי אִי אֶפְשָׁר לְהִתְקָרֵב וְלִכְנֹס לְשׁוּם קְדֻשָּׁה וּלְשׁוּם הַשָּׂגָה וּלְשׁוּם יְדִיעָה מֵהַשֵּׁם יִתְבָּרַךְ כִּי־אִם עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה, וְכָל הַמִּלְחָמוֹת וְכָל הַנִּסְיוֹנוֹת שֶׁיֵּשׁ לְהָאָדָם בַּעֲבוֹדַת הַשֵּׁם, אִי אֶפְשָׁר לְנַצֵּחַ שׁוּם מִלְחָמָה וְלַעֲמֹד בְּנִסָּיוֹן כִּי־אִם עַל־יְדֵי הָאֱמוּנָה הַקְּדוֹשָׁה, כְּמוֹ שֶׁכָּתַב שָׁם בַּתִּקּוּנִים: וְדָוִד כַּד הָוֵי עָאל בִּקְרָבָא, לֹא אִתְרְחִיץ אֶלָּא בָּהּ, כְּמוֹ שֶׁכָּתוּב: "אִם תַּחֲנֶה עָלַי מַחֲנֶה וְכוּ' בְּזֹאת אֲנִי בוֹטֵחַ", הַיְנוּ שֶׁעִקַּר בִּטְחוֹנוֹ וְתִקְוָתוֹ הָיָה בֶּאֱמוּנָה שֶׁנִּקְרָא "זֹאת", דְּהַיְנוּ שֶׁהָיָה יוֹדֵעַ שֶׁהוּא חָזָק בֶּאֱמוּנָה בְּהַשֵּׁם יִתְבָּרַךְ, וְעַל־כֵּן הוּא חָזָק, שֶׁבְּוַדַּאי יַעֲמֹד נֶגֶד כָּל הַמַּחֲנוֹת וְהַמִּלְחָמוֹת שֶׁל הַיֵּצֶר הָרָע וְהַסִּטְרָא־אָחֳרָא, וּבְוַדַּאי יוּכַל לְנַצְּחָם וּלְשַׁבְּרָם, מֵאַחַר שֶׁיֶּשׁ לוֹ אֱמוּנָה חֲזָקָה בְּהַשֵּׁם יִתְבָּרַךְ שֶׁנִּקְרֵאת "זֹאת". וְהַנָּבִיא כְּשֶׁרָאָה אֹרֶךְ הַגָּלוּת, לֹא הָיָה לוֹ תִקְוָה לָצֵאת מִשָּׁם כִּי־אִם עַל־יְדֵי הָאֱמוּנָה שֶׁנִּקְרֵאת "זֹאת", כְּמוֹ שֶׁנֶּאֱמַר: "זֹאת אָשִׁיב אֶל לִבִּי עַל־כֵּן אוֹחִיל וְכוּ'", כִּי מִי שֶׁיִּהְיֶה חָזָק בֶּאֱמוּנָה, בְּוַדַּאי יִזְכֶּה לְנַצֵּחַ הַמִּלְחָמָה וְלָצֵאת מִן הַגָּלוּת בְּוַדַּאי. וְעַיֵּן בַּתִּקּוּנִים, שֶׁהֶאֱרִיךְ בְּעִנְיַן בְּחִינָה שֶׁל "זֹאת", שֶׁיַּעֲקֹב מָסַר "זֹאת" לְבָנָיו, וּמשֶׁה בֵּרַךְ אֶת יִשְׂרָאֵל בְּ"זֹאת", וְהַכֹּל הוֹלֵךְ וְסוֹבֵב עַל הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁנִּקְרֵאת "זֹאת", וְהוּא יְסוֹד הַכֹּל כַּנַּ"ל (הל' גילוח הל' ג,

). 
פא. הָאֱמוּנָה הוּא הַפֶּתַח וְהַשַּׁעַר לִכְנֹס עַל־יָדָהּ בְּהַשָּׂגַת אֱלָקוּתוֹ כַּנַּ"ל, וְהוּא גַּם־כֵּן הַסּוֹף וְהַתַּכְלִית שֶׁל כָּל הַיְדִיעוֹת וְהַהַשָּׂגוֹת, בִּבְחִינַת: "תַּכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע", שֶׁזֶּהוּ בְּחִינַת אֱמוּנָה, כִּי זֶהוּ תַּכְלִית שֶׁל כָּל הַיְדִיעוֹת וְהַהַשָּׂגוֹת, שֶׁיּוֹדְעִין וּמַשִּׂיגִין שֶׁאִי אֶפְשָׁר לֵידַע כְּלָל רַק לְהַאֲמִין בּוֹ יִתְבָּרַךְ. וְזֶה בְּחִינַת: "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אֱלֹקִים"; "אֲנִי" הוּא בְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה, כַּיָּדוּעַ. וְזֶה: "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן", כִּי הַהַתְחָלָה הוּא מֵהָאֱמוּנָה, וְהַסּוֹף הוּא אֱמוּנָה, וְכָל מַה שֶּׁיּוֹדְעִין וּמַשִּׂיגִין יוֹתֵר בְּהַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ, נִתְחַזֵּק הָאֱמוּנָה יוֹתֵר וְיוֹתֵר, וְזֶהוּ עִקַּר תַּכְלִית כָּל הַהַשָּׂגוֹת וִידִיעוֹת. וְעַל־כֵּן צְרִיכִין רַבִּי גָּדוֹל בְּיוֹתֵר שֶׁיּוּכַל לְהַכְנִיס הַשָּׂגַת אֱלָקוּתוֹ אֲפִלּוּ בְּהַפְּחוּתִים וְהַקְּטַנִּים מְאֹד, כִּי כָל הַשָּׂגוֹת וִידִיעוֹת הֵם רַק בִּבְחִינַת מָטֵי וְלָא מָטֵי, בְּגִין דְּלֵית מַחֲשָׁבָה תְּפִיסָא בֵּהּ כְּלָל. כִּי בֶּאֱמֶת עַל־פִּי חָכְמוֹת, בְּוַדַּאי אִי אֶפְשָׁר לְהַשִּׂיגוֹ וְלֵידַע מִמֶּנּוּ יִתְבָּרַךְ כְּלָל, כִּי יוּכַל לִתְעוֹת בְּחָכְמָתוֹ מְאֹד כְּדֶרֶךְ שֶׁתָּעוּ וְנָבוֹכוּ הַמְחַקְּרִים, רַחֲמָנָא לִצְּלַן, עַד שֶׁבָּאוּ לְאֶפִּיקוֹרְסוּת גָּמוּר עַל־יְדֵי טָעוּת חָכְמָתָם הַנְּבוֹכָה, וְעַל־כֵּן הָעִקָּר הִיא הָאֱמוּנָה. אֲבָל צְרִיכִין לְהַחֲיוֹת אֶת הָאֱמוּנָה וּלְחַזְּקָהּ עַל־יְדֵי הַמְשָׁכַת הַחַיּוּת מֵאוֹר הַפָּנִים שֶׁהוּא הַשֵּׂכֶל, וְזֶה נַעֲשֶׂה דַּיְקָא עַל־יְדֵי הַצַּדִּיקֵי הַדּוֹר הַגְּדוֹלִים בְּמַעֲלָה יְתֵרָה דַּיְקָא, שֶׁהֵם עוֹסְקִים לְהַכְנִיס בָּנוּ הָאֱמוּנָה הַקְּדוֹשָׁה, וּבְכָל הַתּוֹרוֹת וְהַהַשָּׂגוֹת שֶׁהֵם מְגַלִּין לָנוּ, עַל־יְדֵי־זֶה הֵם מְחַיִּין וּמְחַזְּקִין אֱמוּנָתֵנוּ הַקְּדוֹשָׁה; כִּי אַף־עַל־פִּי שֶׁאָנוּ רוֹאִין וּמְבִינִים שֶׁאֵין אָנוּ מְבִינִים דִּבְרֵיהֶם כְּלָל, וְחָכְמָתָם הַגְּדוֹלָה נֶעְלָם וְרָחוֹק מֵאִתָּנוּ מְאֹד, אַף־עַל־פִּי־כֵן כָּל חַד כְּפֻם מָה דִּמְשַׁעֵר בְּלִבֵּהּ, יָכוֹל לְהִתְנוֹצֵץ לוֹ מְעַט רְמָזִים גְּדוֹלִים וַחֲזָקִים כַּמָּה צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה; כֻּלֵּי הַאי וְאוּלַי יִזְכֶּה גַּם־כֵּן לֵידַע וּלְהַשִּׂיג קְצָת לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ, אֲשֶׁר נֹעַם עֲרֵבוּת מְתִיקוּת הִתְנוֹצְצוּת אֶחָד אִי אֶפְשָׁר לְשַׁעֵר, וּכְדַאי לִסְבֹּל כָּל הַיִּסּוּרִים שֶׁבָּעוֹלָם וּלְשַׁבֵּר כָּל הַתַּאֲווֹת וּלְהִתְיַגֵּעַ וְלִטְרֹחַ בַּעֲבוֹדַת הַשֵּׁם בְּכָל הַטְרָחוֹת וִיגִיעוֹת בִּמְסִירַת־נֶפֶשׁ בֶּאֱמֶת בִּשְׁבִיל עֲרֵבוּת נְעִימוּת הִתְנוֹצְצוּת אֶחָד. אַשְׁרֵי הַזּוֹכֶה לִרְדֹּף אַחַר זֶה בֶּאֱמֶת. וְעַל־כֵּן רַק הַצַּדִּיקִים הָאֲמִתִּיִּים הַגְּדוֹלִים בְּיוֹתֵר מַכְנִיסִין בָּנוּ הָאֱמוּנָה הַשְּׁלֵמָה דִּקְדֻשָּׁה (שם אותיות י יא). 
פב. עִקַּר כָּל הַנִּסִּים וְהַנִּפְלָאוֹת וְהִתְגַּלּוּת אֱלָהוּת שֶׁהָיָה עַל יְדֵי משֶׁה רַבֵּנוּ, עָלָיו הַשָּׁלוֹם, וְכֵן כָּל הַהַשָּׂגוֹת הַגְּדוֹלוֹת וְהַנִּפְלָאוֹת שֶׁגִּלּוּ לָנוּ שְׁאָר הַצַּדִּיקֵי אֱמֶת, הַכֹּל הוּא רַק כְּדֵי לְחַזֵּק אוֹתָנוּ בֶּאֱמוּנָה שְׁלֵמָה, שֶׁזֶּה תַּכְלִית כָּל הַהַשָּׂגוֹת וְהַיְדִיעוֹת, בְּחִינַת: 'תַּכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע' כַּנַּ"ל. וְזֶה שֶׁכָּתוּב אַחַר כָּל הַנִּסִּים וְהַנִּפְלָאוֹת שֶׁעָשָׂה משֶׁה בִּיצִיאַת מִצְרַיִם, שֶׁהָיָה אָז הִתְגַּלּוּת אֱלָקוּת בְּאוֹר נִפְלָא וְגָדוֹל מְאֹד כַּיָּדוּעַ, וְאַחַר־כָּךְ: וַעֲנַן ה' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְכוּ', וְעַמּוּד אֵשׁ לָיְלָה, וְאַחַר־ כָּךְ הָיָה קְרִיעַת יַם סוּף בְּנִפְלָאוֹת גְּדוֹלוֹת וּבְהִתְגַּלּוּת אֱלָקוּת גָּדוֹל מְאֹד, עַד שֶׁרָאֲתָה שִׁפְחָה עַל הַיָּם וְכוּ' כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל. אַחַר כָּל זֶה כְּתִיב: "וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְכוּ', וַיַּאֲמִינוּ בַּה'" - רְאֵה וְהָבֵן וְהַבֵּט, כִּי אַחַר כָּל הַהַשָּׂגוֹת וְהַיְדִיעוֹת וְהַמּוֹפְתִים, עֲדַיִן צְרִיכִין לֶאֱמוּנָה, כִּי כָל הַנַּ"ל לֹא הָיָה אֶלָּא בִּשְׁבִיל חִזּוּק הָאֱמוּנָה, כָּל חַד כְּפֻם מָה דִּמְשַׁעֵר בְּלִבֵּהּ, כִּי לְעוֹלָם צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה וּלְהַאֲמִין בְּהַשֵּׁם יִתְבָּרַךְ וּבְהַצַּדִּיקֵי אֱמֶת בִּפְשִׁיטוּת בְּלִי שׁוּם חָכְמוֹת, כִּי הָעִקָּר הוּא הָאֱמוּנָה הַפְּשׁוּטָה כַּנַּ"ל (שם

). 
פו. הָאֱמוּנָה אַף עַל פִּי שֶׁהִיא לְמַטָּה מֵהַשֵּׂכֶל כַּיָּדוּעַ, כִּי אֵין אֱמוּנָה כִּי־אִם בְּמַה שֶּׁאֵין הַשֵּׂכֶל מֵבִין, אַף־עַל־פִּי־כֵן שָׁרְשָׁהּ נִמְשָׁךְ מִמָּקוֹם גָּבֹהַּ וְעֶלְיוֹן מְאֹד, שֶׁהוּא גָּבֹהַּ מִכָּל הַשִּׂכְלִיִּים. כִּי בְּחִינַת הָאֱמוּנָה הוּא בְּחִינַת "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן", בְּחִינַת "מַגִּיד מֵרֵאשִׁית אַחֲרִית", בְּחִינַת "סוֹף מַעֲשֶׂה בְּמַחֲשָׁבָה תְּחִלָּה", וְכַמְבֹאָר כָּל זֶה בְּמָקוֹם אַחֵר (שם). 
פז. אֱמֶת וֶאֱמוּנָה הֵם שְׁנֵיהֶם אֶחָד. כִּי מִי שֶׁמַּאֲמִין בְּהָאֱמֶת, הוּא מְקֻשָּׁר אֶל הָאֱמֶת כְּאִלּוּ הוּא יוֹדֵעַ וּמַשִּׂיג אוֹתוֹ בְּשִׂכְלוֹ הֵיטֵב, וְאֵין חִלּוּק בֵּינֵיהֶם כְּלָל; אַדְּרַבָּה, עִקַּר הָאֱמֶת אִי אֶפְשָׁר לֵידַע וּלְהַשִּׂיג מֵחֲמַת רִבּוּי אוֹר, כִּי־אִם עַל־יְדֵי אֱמוּנָה, כִּי אֱמֶת וֶאֱמוּנָה הֵם בְּחִינַת אִישׁ וְאִשָּׁה, שֶׁעַל זֶה נֶאֱמַר: "לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ", הַיְנוּ כִּי אִי אֶפְשָׁר לֵהָנוֹת מֵהָאֱמֶת וּלְהוֹלִיד מִמֶּנּוּ לְבַדּוֹ, מֵחֲמַת שֶׁאִי אֶפְשָׁר לְקַבֵּל עֶצֶם אוֹר הָאֱמֶת, עַל־כֵּן אָמַר הַקָּדוֹשׁ־בָּרוּךְ־הוּא: "אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ", הַיְנוּ הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהִיא בְּחִינַת "אֵשֶׁת חַיִל", בְּחִינַת "אִשָּׁה יִרְאַת ה'", בְּחִינַת הַכַּלָּה הַקְּדוֹשָׁה הַמְשֻׁבַּחַת בְּכָל סֵפֶר שִׁיר־הַשִּׁירִים, כִּי הָאֱמוּנָה הַקְּדוֹשָׁה נִקְרֵאת "כַּלָּה", כִּי הִיא כְּלוּלָה מֵהַכֹּל, כִּי כָּל הַשָּׂגוֹת אֱלָקוּת וְכָל הַיְדִיעוֹת הַגְּבוֹהוֹת, הַכֹּל אֵין יְכוֹלִין לְקַבֵּל כִּי־אִם עַל־יְדֵי אֱמוּנָה, כִּי הָאֱמוּנָה הִיא עֶצֶם מֵעֲצָמָיו וּבָשָׂר מִבְּשָׂרוֹ שֶׁל הָאֱמֶת, כִּי שְׁנֵיהֶם אֶחָד וְאִי אֶפְשָׁר לָזֶה בְּלֹא זֶה, וְכָל קִיּוּם הָעוֹלָם עַל־יְדֵי שְׁנֵיהֶם דַּיְקָא, בִּבְחִינַת "עַל־כֵּן יַעֲזָב־אִישׁ אֶת־אָבִיו וְאֶת אִמּוֹ", הַיְנוּ שֶׁצְּרִיכִין לַעֲזֹב אֶת כָּל הַחָכְמוֹת שֶׁהֵם בְּחִינַת אָב לַחָכְמָה וְאֵם לַבִּינָה, רַק לְדַבֵּק עַצְמוֹ בְּהָאִשָּׁה יִרְאַת־הַשֵּׁם, שֶׁהִיא בְּחִינַת הָאֱמוּנָה הַקְּדוֹשָׁה, שֶׁעִקַּר הִתְגַּלּוּת אֲמִתַּת הָאֱמֶת הוּא עַל־יָדָהּ, בִּבְחִינַת "וְהָיוּ לְבָשָׂר אֶחָד", שֶׁהָאֱמֶת וְהָאֱמוּנָה הֵם אֶחָד בְּתַכְלִית הָאַחְדוּת, כִּי מֵאַחַר שֶׁמַּאֲמִין בְּהָאֱמֶת לַאֲמִתּוֹ, אֲזַי נִכְלָל הָאֱמוּנָה בְּהָאֱמֶת בְּתַכְלִית הָאַחְדוּת, וְעַל־יְדֵי־זֶה נוֹלָדִים כָּל הַהַשָּׂגוֹת לָדַעַת מֵאֲמִתַּת אֱלָקוּתוֹ יִתְבָּרַךְ, כִּי אִי אֶפְשָׁר לָדַעַת מִמֶּנּוּ יִתְבָּרַךְ כִּי־אִם עַל־יְדֵי הִתְחַבְּרוּת אֱמֶת וֶאֱמוּנָה, כִּי אֱמֶת בְּלֹא אֱמוּנָה אִי אֶפְשָׁר לְקַבֵּל מֵחֲמַת רִבּוּי אוֹר כַּנַּ"ל, וֶאֱמוּנָה בְּלֹא אֱמֶת, בְּוַדַּאי אֵינוֹ כְּלוּם, כִּי כְּשֶׁאֵינוֹ מִסְתַּכֵּל עַל הָאֱמֶת, אֲזַי יוּכַל לָבוֹא לֶאֱמוּנוֹת כָּזְבִּיּוֹת, חַס וְשָׁלוֹם, כִּי עִקַּר קִיּוּם שֶׁל הָאֱמוּנָה הַקְּדוֹשָׁה הוּא עַל־יְדֵי אֱמֶת, בְּחִינַת "צֶדֶק כַּד אִתְחַבָּרַת בֶּאֱמֶת, אִתְעֲבִידַת אֱמוּנָה", הַיְנוּ כְּשֶׁמִּסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ, אָז בְּוַדַּאי רוֹאֶה בְּעֵינָיו שֶׁרָאוּי לְהַאֲמִין בַּאֲבוֹתֵינוּ הַקְּדוֹשִׁים וּבְהַצַּדִּיקֵי־אֱמֶת שֶׁמַּזְהִירִים אוֹתָנוּ לְקַיֵּם תּוֹרָתֵנוּ הַקְּדוֹשָׁה, וְאָז אִתְעֲבִידַת אֱמוּנָה, שֶׁזּוֹכִין לֶאֱמוּנָה הַקְּדוֹשָׁה בִּשְׁלֵמוּת, וְאָז נִכְלָל אֱמֶת וֶאֱמוּנָה יַחַד, כִּי בֶּאֱמֶת שְׁנֵיהֶם אֶחָד כַּנַּ"ל, וְעַל־יְדֵי־זֶה נוֹלָדִין כָּל הַהַשָּׂגוֹת וְהַיְדִיעוֹת, כִּי עַל־יְדֵי אֱמוּנָה זוֹכִין אַחַר־כָּךְ לְהַשָּׂגוֹת וִידִיעוֹת גְּבוֹהוֹת מְאֹד, כַּמְבֹאָר בְּמָקוֹם אַחֵר, וְעַל־יְדֵי אֵלּוּ הַיְדִיעוֹת מוֹלִידִין נְפָשׁוֹת מַמָּשׁ, כִּי כָּל מַה שֶּׁהַצַּדִּיקִים זוֹכִין לְהַשִּׂיג הַשָּׂגוֹת גְּבוֹהוֹת בְּיוֹתֵר עַל־יְדֵי הִתְחַבְּרוּת אֱמֶת וֶאֱמוּנָה כַּנַּ"ל, עַל־יְדֵי־זֶה יְכוֹלִין לְהַכְנִיס הָאֱמוּנָה הַקְּדוֹשָׁה בְּלֵב כָּל הַנְּפָשׁוֹת הַיְרוּדוֹת וְהָרְחוֹקוֹת מִמֶּנּוּ יִתְבָּרַךְ מְאֹד מְאֹד, עַד שֶׁנֶּחְשָׁב כְּאִלּוּ עֲשָׂאָן כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל, וּכְאִלּוּ נוֹלְדוּ אֵלּוּ הַנְּפָשׁוֹת הַיּוֹם מֵחָדָשׁ כַּיָּדוּעַ (שם

). 
פח. קֹדֶם אֲכִילַת עֵץ הַדַּעַת כְּתִיב: "וַיִּהְיוּ שְׁנֵיהֶם עֲרוּמִּים הָאָדָם וְאִשְׁתּוֹ", כִּי אָז הָיוּ הָאֱמֶת וְהָאֱמוּנָה, שֶׁהֵם בְּחִינַת אִישׁ וְאִשְׁתּוֹ, עֲרֻמִּים בְּלִי שׁוּם לְבוּשׁ, כִּי הָיוּ יְכוֹלִין אָז לְקַבֵּל אוֹר הָאֱמֶת וְהָאֱמוּנָה בְּלִי לְבוּשִׁין, כִּי הָיוּ הַכֹּל רוֹאִין הָאֱמֶת וְהָאֱמוּנָה, שֶׁהָיוּ רוֹאִין עַיִן בְּעַיִן שֶׁאֲמִתַּת יְדִיעָתוֹ יִתְבָּרַךְ הוּא עַל־יְדֵי אֱמוּנָה, שֶׁזֶּה בְּחִינַת 'תַּכְלִית הַיְדִיעָה, אֲשֶׁר לֹא נֵדַע', שֶׁהִשִּׂיגוּ אֶת הָאֱמֶת בְּתַכְלִית הַיְדִיעָה עַד שֶׁרָאוּ וְיָדְעוּ בִּידִיעָה בְּרוּרָה אֲמִתַּת אֱלָקוּתוֹ יִתְבָּרַךְ, שֶׁאִי אֶפְשָׁר לֵידַע מִּמֶּנּוּ כִּי־אִם עַל־יְדֵי אֱמוּנָה, כְּמוֹ שֶׁיֵּשׁ גַּם עַתָּה כַּמָּה דְּבָרִים שֶׁאִם לֹא הָיוּ רוֹאִין אוֹתָם בָּעֵינַיִם בְּכָל יוֹם, הָיָה קָשֶׁה לְהַאֲמִין בָּהֶם, כְּגוֹן שֶׁיִּהְיֶה מִטִּפָּה סְרוּחָה נוֹצָר בֶּן־אָדָם, וְיִהְיֶה בְּבֶטֶן אִמּוֹ תִּשְׁעָה חֳדָשִׁים, וְאַחַר־כָּךְ יִתְגַּדֵּל מִזֶּה בֶּן־אָדָם הַשָּׁלֵם בְּדַעַת וּבְצוּרָה וְכוּ', וְכֵן מִגַּרְעִין אֶחָד הַנִּזְרָע בָּאָרֶץ וְנִתְבַּלֶּה, יִתְגַּדֵּל מִמֶּנּוּ אִילָן יָפֶה וְגָדוֹל עִם הַרְבֵּה עֲנָפִים וּפֵרוֹת - בְּוַדַּאי לֹא הָיָה הַשֵּׂכֶל הַפָּשׁוּט מַסְכִּים לָזֶה בְּשׁוּם אֹפֶן, וְכֵן בְּכָל פְּרָטֵי הַבְּרִיאָה. וּבֶאֱמֶת נֶאֱמַר עַל זֶה: "מַה גָּדְלוּ מַעֲשֶׂיךָ ה'", וְנֶאֱמַר: "מָה רַבּוּ מַעֲשֶׂיךָ ה'". נִמְצָא שֶׁהָאָדָם רוֹאֶה בְּעֵינָיו דְּבָרִים שֶׁאֵינוֹ מְבִינָם בְּשֵׂכֶל, שֶׁעַל־ יְדֵי־זֶה מֻכְרָח לְהִתְחַזֵּק בֶּאֱמוּנָה. וְקֹדֶם הַחֵטְא הָיְתָה יְדִיעַת הָאֱמֶת לַאֲמִתּוֹ, הַיְנוּ הַיְדִיעָה מִמֶּנּוּ יִתְבָּרַךְ, הָיְתָה פְּשׁוּטָה וּבְרוּרָה בְּתַכְלִית הַבֵּרוּר, עַד שֶׁהָיוּ יוֹדְעִין כִּי אִי אֶפְשָׁר לֵידַע מִמֶּנּוּ כִּי־אִם עַל־יְדֵי אֱמוּנָה, וּבֶאֱמֶת אֱמֶת וֶאֱמוּנָה שְׁנֵיהֶם אֶחָד בְּתַכְלִית הָאַחְדוּת כַּנַּ"ל; אֲבָל אַחַר הַחֵטְא, שֶׁנֶּאֱחַז בָּהֶם זֻהֲמַת הַנָּחָשׁ, עַל־יְדֵי־זֶה אִי אֶפְשָׁר לְקַבֵּל עַתָּה אוֹר הָאֱמֶת וְהָאֱמוּנָה כִּי־אִם עַל־יְדֵי לְבוּשִׁין, שֶׁהֵם בְּחִינַת כְּלַל הַתּוֹרָה הַקְּדוֹשָׁה, שֶׁנִּתְלַבְּשָׁה בְּכַמָּה לְבוּשִׁין בְּסוֹד 'חֲלוּקָא דְּרַבָּנָן'. וְכֵן כָּל הַחִדּוּשֵׁי־תוֹרָה שֶׁמְּחַדְּשִׁין לָנוּ הַצַּדִּיקִים שֶׁבְּכָל דּוֹר וּמְבָאֲרִין לָנוּ דַּרְכֵי הַתּוֹרָה הַקְּדוֹשָׁה שֶׁיְּסוֹדָהּ אֱמֶת וֶאֱמוּנָה, הַיְנוּ שֶׁעַכְשָׁו אִי אֶפְשָׁר לְקַבֵּל הָאֱמֶת וְהָאֱמוּנָה בִּשְׁלֵמוּת כִּי־אִם עַל־יְדֵי כַּמָּה לְבוּשִׁין וְהַקְדָּמוֹת שֶׁהַצַּדִּיקִים מְבָאֲרִים לָנוּ עַל־יְדֵי נִפְלְאוֹת חִדּוּשֵׁי תּוֹרָתָם, שֶׁהַכֹּל הוּא רַק בִּשְׁבִיל לְהַמְשִׁיךְ בָּנוּ אֱמוּנָה שְׁלֵמָה בְּאֹפֶן שֶׁנִּזְכֶּה עַל־יְדֵי־זֶה לְקַבֵּל אוֹר הָאֱמֶת, וְהֵם בְּחִינַת לְבוּשִׁים שֶׁמַּלְבִּישִׁים בָּהֶם אֶת הָאֱמֶת וְהָאֱמוּנָה, וּמִשָּׁם נִמְשָׁכִין כָּל הַמַּלְבּוּשִׁים שֶׁבָּעוֹלָם שֶׁנִּתְהַוּוּ אַחַר הַחֵטְא, שֶׁהֵם תִּקּוּן גָּדוֹל כְּדֵי שֶׁלֹּא יִהְיֶה כֹּחַ לְזֻהֲמַת הַנָּחָשׁ, חַס וְשָׁלוֹם, לְהִתְאַחֵז בְּהָאֱמֶת וְהָאֱמוּנָה וְלִפְגֹּם אוֹתָם, חַס וְשָׁלוֹם. אַךְ הַמַּלְבּוּשִׁים צְרִיכִין גַּם־כֵּן תִּקּוּן וּשְׁמִירָה, וְתִקּוּנָם הוּא עַל־יְדֵי מִצְוַת צִיצִת, שֶׁעַל־יְדֵי מִצְוַת צִיצִת עִקַּר הַמְשָׁכַת הָאֱמֶת וְהָאֱמוּנָה, כַּמְבֹאָר בִּפְנִים. וְזֶה בְּחִינַת הָאִסּוּר שֶׁ"לֹּא יִלְבַּשׁ גֶּבֶר שִׂמְלַת אִשָּׁה וְכוּ'", כִּי יֵשׁ לְבוּשֵׁי אֱמֶת וּלְבוּשֵׁי אֱמוּנָה, שֶׁזֶּה בְּחִינַת לְבוּשֵׁי אִישׁ וּלְבוּשֵׁי אִשָּׁה, אַךְ דֶּרֶךְ הַסִּטְרָא־אָחֳרָא, שֶׁהֵם הֵיכְלֵי הַתְּמוּרוֹת, שֶׁהֵם מְמִירִין וּמַחֲלִיפִין וְרוֹצִים לִסְתֹּר וּלְהַעְלִים אֶת הָאֱמֶת דִּקְדֻשָּׁה, הַיְנוּ מַה שֶּׁהַשֵּׂכֶל דִּקְדֻשָּׁה מַשִּׂיג וּמֵבִין שֶׁכָּךְ הוּא הָאֱמֶת, וְהֵם רוֹצִים לְסָתְרוֹ בְּהָאֱמוּנוֹת כָּזְבִּיּוֹת שֶׁלָּהֶם, שֶׁזֶּה בְּחִינָה שֶׁמַּלְבִּישִׁים וּמַעֲלִימִין הָאֱמֶת עַל־יְדֵי לְבוּשֵׁי אִשָּׁה. וְכֵן בְּמָקוֹם שֶׁמְּבִינִים עַל־פִּי הָאֱמֶת שֶׁצְּרִיכִין לְהַאֲמִין, הֵם רוֹצִים לִסְתֹּר הָאֱמוּנָה דִּקְדֻשָּׁה עַל־יְדֵי הָאֱמֶת הַמְדֻמֶּה וְהַמֻּטְעֶה שֶׁלָּהֶם, כִּי מַה שֶּׁהַשֵּׂכֶל וְהַיְדִיעָה מַסְכִּים לָזֶה, זֶה בְּחִינַת אֱמֶת, וּמֵחֲמַת שֶׁאֵין הַשֵּׂכֶל הַמְשֻׁבָּשׁ שֶׁלָּהֶם מַסְכִּים לְהָאֱמוּנָה הַקְּדוֹשָׁה, עַל־כֵּן רוֹצִים לְסָתְרָהּ וּלְהַעְלִימָהּ, חַס וְשָׁלוֹם, שֶׁזֶּה בְּחִינָה שֶׁמַּלְבִּישִׁין הָאִשָּׁה, שֶׁהִיא בְּחִינַת אֱמוּנָה, שִׂמְלַת גֶּבֶר, כִּי בְּמָקוֹם שֶׁהַשֵּׂכֶל הָאֱמֶת מֵבִין שֶׁאִי אֶפְשָׁר לְהַשִּׂיג, רַק שֶׁצְּרִיכִין לִסְמֹךְ עַל אֱמוּנָה, שָׁם הֵם רוֹצִים דַּיְקָא לְהָבִין בְּשִׂכְלָם, שֶׁזֶּה שֹׁרֶשׁ כָּל הַכְּפִירוֹת וְהָאֱמוּנוֹת כָּזְבִּיּוֹת. וְזֶה שֶׁפֵּרֵשׁ רַשִׁ"י שֶׁדָּבָר זֶה גּוֹרֵם לְנִאוּף, כִּי עִקַּר הַנִּאוּף נִמְשָׁךְ מִכְּפִירוֹת, כַּמְבֹאָר בִּפְנִים. אֲבָל הַשֵּׁם יִתְבָּרַךְ הִבְדִּילָנוּ מֵהֶם וְהֵאִיר בָּנוּ נְקֻדַּת הָאֱמֶת עַל־יְדֵי הַצַּדִּיקִים אֲמִתִּיִּים שֶׁמַּלְבִּישִׁין אֶת הָאֱמֶת וְהָאֱמוּנָה בִּבְחִינַת 'חֲלוּקָא דְּרַבָּנָן', לְבוּשֵׁי קֹדֶשׁ, שֶׁהֵם חִדּוּשֵׁי תּוֹרָתָם הַנּוֹרָאִים, שֶׁעַל־יְדֵי־זֶה הֵם מַכְנִיסִין בָּנוּ אֱמֶת וֶאֱמוּנָה, שֶׁעַל־יְדֵי־זֶה אָנוּ זוֹכִין לְהִסְתַּכֵּל עַל הָאֱמֶת, הַיְנוּ עַל הַסְכָּמַת הַשֵּׂכֶל הָאֲמִתִּי, בִּכְדֵי לָסוּר עַל־יְדֵי־זֶה מֵאֱמוּנוֹת כָּזְבִּיּוֹת, שֶׁבִּשְׁבִיל זֶה עִקַּר שְׁלֵמוּת הָאֱמוּנָה הוּא עַל־יְדֵי אֱמֶת כַּנַּ"ל. וְכֵן עַל־יְדֵי הָאֱמֶת הַזֶּה אָנוּ זוֹכִין לְהִתְחַזֵּק בֶּאֱמוּנָה הַקְּדוֹשָׁה בְּמָקוֹם שֶׁאִי אֶפְשָׁר לְהַשִּׂיג וּלְהָבִין בְּשׁוּם שֵׂכֶל, אַף־עַל־פִּי־כֵן הֵם מְבִינִים מֵרָחוֹק שֶׁכָּךְ הוּא הָאֱמֶת, רַק שֶׁאִי אֶפְשָׁר לְהָבִין וּלְהַשִּׂיג, וּצְרִיכִין לְהִתְחַזֵּק רַק בֶּאֱמוּנָה הַקְּדוֹשָׁה, כִּי בֶּאֱמֶת אִי אֶפְשָׁר לָדַעַת וּלְהַשִּׂיג בִּשְׁלֵמוּת אוֹתוֹ יִתְבָּרַךְ וְטַעֲמֵי הַמִּצְו?ֹת שֶׁל הַתּוֹרָה הַקְּדוֹשָׁה, וְכֵן קְדֻשַּׁת הַצַּדִּיקִים אֲמִתִּיִּים, רַק עַל־יְדֵי אֱמוּנָה כַּנַּ"ל (שם אותיות יא יב יג). 
פט. הַטְּבִילָה וְהַטָּהֳרָה בְּמִקְוֶה מְסֻגָּל לְגַדֵּל וּלְהַשְׁלִים אֶת הָאֱמוּנָה (שם

). 
צ. אִי אֶפְשָׁר לְהִתְדַּבֵּק וּלְהִתְקָרֵב לְהַשֵּׁם יִתְבָּרַךְ בֶּאֱמֶת כִּי־אִם עַל־יְדֵי אֱמוּנָה, שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה כֻּלָּהּ. כָּל הָעוֹלָמוֹת, כָּל הַנֶּאֱצָלִים וְהַנִּבְרָאִים, הַנּוֹצָרִים וְהַנַּעֲשִׂים, כֻּלָּם עוֹמְדִים רַק עַל אֱמוּנָה, כְּמוֹ שֶׁנֶּאֱמַר: "וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה". וְכָל תִּקּוּן הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי שֶׁעַל־יְדֵי־זֶה הָיְתָה כָּל הַבְּרִיאָה, הַכֹּל הָיָה בִּבְחִינַת אֱמוּנָה. כִּי זֶה יָדוּעַ בִּכְתָבִים, שֶׁתְּחִלַּת הַצִּמְצוּם הָיָה בִּבְחִינַת מַלְכוּת שֶׁבְּאֵין־סוֹף, וּמַלְכוּת הוּא בְּחִינַת אֱמוּנָה כַּיָּדוּעַ. כִּי הַשֵּׁם יִתְבָּרַךְ הִסְתַּכֵּל בְּחָכְמָתוֹ הַקְּדוֹשָׁה, שֶׁאִי אֶפְשָׁר לְהַכִּירוֹ וְלֵידַע מִמֶּנּוּ יִתְבָּרַךְ (שֶׁבִּשְׁבִיל זֶה הָיְתָה כָּל הַבְּרִיאָה, 'בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ') עַל־יְדֵי שׁוּם מִדָּה וְשׁוּם שֵׂכֶל וּסְפִירָה, כִּי־אִם עַל־יְדֵי אֱמוּנָה שֶׁהִיא בְּחִינַת מַלְכוּת שֶׁהוּא תְּחִלַּת הַצִּמְצוּם, שֶׁעַל־יָדָהּ עִקַּר הִתְגַּלּוּת כָּל הַמִּדּוֹת וְכָל הָעוֹלָמוֹת. וְזֶהוּ עִקַּר תְּחִלַּת הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, דְּהַיְנוּ שֶׁצִּמְצֵם אֱלָקוּתוֹ כִּבְיָכוֹל, שֶׁהוּא הַשֵּׂכֶל, כִּי הַשֵּׁם יִתְבָּרַךְ הוּא עֶצֶם הַחָכְמָה כִּבְיָכוֹל, כַּיָּדוּעַ, וּכְשֶׁפִּנָּה הַשֵּׂכֶל מִשָּׁם, נִשְׁאַר הַמָּקוֹם פָּנוּי כִּבְיָכוֹל בְּלִי שֵׂכֶל, וְלֹא נִשְׁאַר שָׁם כִּי־אִם בְּחִינַת אֱמוּנָה, דְּהַיְנוּ שֶׁמַּאֲמִינִים בְּהָאֱמֶת בֶּאֱמוּנָה לְבַד בְּלִי שׁוּם שֵׂכֶל וְחָכְמָה. וְתֵכֶף כְּשֶׁנַּעֲשָׂה הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, דְּהַיְנוּ בְּחִינַת אֱמוּנָה, אָז תֵּכֶף הִמְשִׁיךְ אֱלָקוּתוֹ לְתוֹךְ אוֹתוֹ הֶחָלָל הַפָּנוּי, שֶׁזֶּה בְּחִינַת כְּלַל הַמִּדּוֹת וְכָל הָעוֹלָמוֹת, מֵרֵאשִׁית נְקֻדַּת הַבְּרִיאָה שֶׁהוּא תְּחִלַּת הָאֲצִילוּת, עַד סוֹף נְקֻדַּת הַמֶּרְכָּז שֶׁל עוֹלָם הַגַּשְׁמִי הַזֶּה, וְכָל מַעֲשֵׂהוּ בֶּאֱמוּנָה כַּנַּ"ל. כִּי אַחַר־כָּךְ כְּשֶׁנִּתְהַוָּה מִדַּת הָאֱמוּנָה שֶׁהוּא תְּחִלַּת הַצִּמְצוּם, אָז יֵשׁ בְּכֹחַ לְגַלּוֹת אֱלָקוּתוֹ יִתְבָּרַךְ עַל־יְדֵי צִמְצוּמִים שֶׁל הַשֵּׂכֶל, שֶׁהֵם כְּלַל כָּל הַמִּדּוֹת וְהַסְּפִירוֹת, כִּי עַל־יְדֵי אֱמוּנָה זוֹכִין אַחַר־כָּךְ לְהָבִין בְּשֵׂכֶל, כְּמוֹ שֶׁנֶּאֱמַר: "וְאֵרַשְׂתִּיךְ לִי בֶּאֱמוּנָה", (וְהָדַר) "וְיָדַעַתְּ אֶת ה'", כִּי בַּתְּחִלָּה, קֹדֶם תִּקּוּן הַצִּמְצוּם שֶׁל הָאֱמוּנָה, אִי אֶפְשָׁר לְהָבִין בְּשֵׂכֶל, כִּי עֲדַיִן הַכֹּל אֶצְלוֹ בִּבְחִינַת אֵין־ סוֹף, כִּי כָּל מַה שֶּׁאֵין הָאָדָם מֵבִין, הוּא אֶצְלוֹ בִּבְחִינַת אֵין־סוֹף כַּיָּדוּעַ, כִּי אַף־עַל־ פִּי שֶׁבָּעוֹלָם הָעֶלְיוֹן וּבַמַּדְרֵגָה הָעֶלְיוֹנָה מִזֶּה, הַשָּׂגָה זוֹ הִיא בְּחִינַת צִמְצוּם, אֲבָל בָּעוֹלָם הַנָּמוּךְ מִמֶּנּוּ, הוּא עֲדַיִן בְּחִינַת אֵין־סוֹף, כִּי מַלְכוּת דִּיצִירָה הוּא בְּחִינַת אֵין־סוֹף נֶגֶד כֶּתֶר דַּעֲשִׂיָּה, כַּיָּדוּעַ וּמוּבָן. וְעַל־כֵּן בַּתְּחִלָּה אִי אֶפְשָׁר לְהָאָדָם שֶׁיָּבִין שׁוּם דָּבָר וְשׁוּם הַשָּׂגָה, כִּי הַכֹּל אֶצְלוֹ בְּחִינַת אֵין־סוֹף, וְצָרִיךְ שֶׁיִּהְיֶה לוֹ בַּתְּחִלָּה אֱמוּנָה שְׁלֵמָה לְבַד בְּלִי שׁוּם שֵׂכֶל, וְזֶהוּ בְּחִינַת הַצִּמְצוּם כַּנַּ"ל; וְאָז כְּשֶׁהוּא חָזָק בֶּאֱמוּנָתוֹ, אָז הַשֵּׁם יִתְבָּרַךְ מֵאִיר עֵינָיו וְזוֹכֶה לְהָבִין אַחַר־כָּךְ הַדָּבָר בְּשִׂכְלוֹ, שֶׁזֶּה בְּחִינַת הַמְשָׁכַת הָאוֹרוֹת וְהַמִּדּוֹת לְתוֹךְ הֶחָלָל הַפָּנוּי, לְתוֹךְ הַצִּמְצוּם, שֶׁהוּא בְּחִינַת אֱמוּנָה כַּנַּ"ל, כִּי הָאֱמוּנָה הוּא הַצִּמְצוּם וְהַכְּלִי שֶׁל כָּל הַמִּדּוֹת, שֶׁהֵם כֻּלָּם בְּחִינַת צִמְצוּמֵי הַשֵּׂכֶל מֵעִלָּה לְעָלוּל, מִשֵּׂכֶל עֶלְיוֹן לְשֵׂכֶל הַתַּחְתּוֹן, לְהַשִּׂיג עַל־יָדָם הַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ, וְכֻלָּם אֵין לָהֶם כֹּחַ לְגַלּוֹת וּלְהוֹלִיד שׁוּם דַּעַת וְשׁוּם הַשָּׂגָה בּוֹ יִתְבָּרַךְ, כִּי־אִם עַל־יְדֵי הָאֱמוּנָה לְבַד, כִּי הָאֱמוּנָה הוּא הַכְּלִי וְהַצִּמְצוּם שֶׁל כֻּלָּם. וְזֶה בְּחִינַת מַה שֶּׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, דְּלֵית רְשׁוּ לְשׁוּם סְפִירָה וְכוּ' לַאֲרָקָא בִּרְכָאן בַּר מִנָּהּ, כִּי עַל־יְדֵי אֱמוּנָה בְּחִינַת מַלְכוּת, עַל־יָדָהּ דַּיְקָא עִקַּר הִתְגַּלּוּת הַדַּעַת שֶׁל הַשָּׂגַת אֱלָקוּתוֹ יִתְבָּרַךְ (הל' נדה, הלכה ב). 
צא. זֶה הַצִּמְצוּם שֶׁל הֶחָלָל הַפָּנוּי, הַיְנוּ מַה שֶּׁבְּחָכְמָתוֹ הַנִּפְלָאָה צִמְצֵם חָכְמָתוֹ כָּל־כָּךְ, עַד אֲשֶׁר סִלֵּק הַחָכְמָה וְהַשֵּׂכֶל לְגַמְרֵי, עַד שֶׁנִּשְׁאַר הַמָּקוֹם כִּבְיָכוֹל פָּנוּי מִכָּל הַשִּׂכְלִיּוּת וְהַחָכְמוֹת שֶׁהֵם עַצְמוּת אֱלָקוּתוֹ יִתְבָּרַךְ, וְלֹא נִשְׁאַר מִן הַשֵּׂכֶל כִּי־ אִם כֹּחַ הָאֱמוּנָה, שֶׁבָּרָא כֹּחַ בְּהָעוֹלָמוֹת וְהַנִּבְרָאִים שֶׁיִּהְיֶה לָהֶם שֵׂכֶל וָדַעַת לְהַאֲמִין בּוֹ יִתְבָּרַךְ בְּלִי שׁוּם שֵׂכֶל. וּבֶאֱמֶת זֶה הַצִּמְצוּם הוּא פֶּלֶא גָּדוֹל, כַּמּוּבָא בְּמָקוֹם אַחֵר, כִּי אֱמוּנָה הוּא פֶּלֶא גָּדוֹל, כְּמוֹ שֶׁנֶּאֱמַר: "אוֹדֶה שִׁמְךָ כִּי עָשִׂיתָ פֶּלֶא, עֵצוֹת מֵרָחֹק אֱמוּנָה אֹמֶן", כִּי אֱמוּנָה הוּא נִפְלְאוֹת תְּמִים דֵּעִים, כִּי בְּדָבָר שֶׁהַשֵּׂכֶל מֵבִין, אֵין צְרִיכִין לְהַאֲמִין וְאֵינוֹ נִקְרָא אֱמוּנָה, מֵאַחַר שֶׁגַּם הַשֵּׂכֶל מֵבִין זֶה, וְעִקַּר הָאֱמוּנָה הוּא בְּמַה שֶּׁאֵין מְבִינִים בַּשֵּׂכֶל. וְאִם־כֵּן, מֵאַחַר שֶׁאֵין הַשֵּׂכֶל מֵבִין וּמַשִּׂיג שָׁם, מֵהֵיכָן יָבוֹא לְדַעְתּוֹ שֶׁיַּאֲמִין בָּזֶה? אַךְ בֶּאֱמֶת הוּא נִפְלְאוֹת תְּמִים דֵּעִים, שֶׁבָּרָא בְּחָכְמָתוֹ הַגְּדוֹלָה כֹּחַ בְּשֵׂכֶל הָאָדָם, שֶׁיִּהְיֶה לוֹ כֹּחַ לְצַמְצֵם וּלְסַלֵּק דַּעְתּוֹ וּלְהַאֲמִין בֶּאֱמוּנָה לְבַד עַל־יְדֵי כֹּחַ הָרְשִׁימוּ שֶׁנִּשְׁאַר בְּהַדַּעַת גַּם לְאַחַר הִסְתַּלְּקוּת הַדַּעַת, כִּי אַף־עַל־גַב דְּאִיהוּ לָא חָזֵי, מַזְּלֵהּ חָזֵי, כִּי אַף־עַל־פִּי שֶׁאֵינוֹ מֵבִין הַדָּבָר בְּשִׂכְלוֹ, אַף־עַל־פִּי־כֵן מֵבִין מֵרָחוֹק שֶׁרָאוּי לוֹ לְהַאֲמִין, כִּי כְּשֶׁרוֹצֶה לְהִסְתַּכֵּל עַל הָאֱמֶת, הוּא מֵבִין בְּבֵרוּר שֶׁצְּרִיכִין לְהַאֲמִין, כִּי הוּא מֵבִין זֶה בְּעַצְמוֹ שֶׁאִי אֶפְשָׁר לְהָבִין הַדָּבָר בְּשׁוּם שֵׂכֶל, רַק צְרִיכִין לְהַאֲמִין בֶּאֱמוּנָה לְבָד (שם

). 
צב. כְּשֶׁרוֹדֵף שִׂכְלוֹ לָדַעַת וּלְהִסְתַּכֵּל בְּמַה שֶּׁאֵין לוֹ רְשׁוּת וְאֵינוֹ רוֹצֶה לִסְמֹךְ עַל הָאֱמוּנָה לְבַד, עַל־יְדֵי־זֶה גּוֹרְמִין שְׁבִירַת כֵּלִים, חַס וְשָׁלוֹם, דְּהַיְנוּ שֶׁנִּשְׁבָּר כְּלִי הָאֱמוּנָה, מֵאַחַר שֶׁאֵינוֹ רוֹצֶה לִסְמֹךְ עַל הָאֱמוּנָה לְבַד, וְרוֹצֶה לָדַעַת וּלְהָבִין דַּיְקָא בְּלִי אֱמוּנָה; נִמְצָא שֶׁמַּפְשִׁיט אֶת הַדַּעַת מִן הָאֱמוּנָה, שֶׁזֶּה בְּחִינַת שְׁבִירַת כֵּלִים וּמִיתַת הַמְּלָכִים, כִּי נִשְׁאֲרוּ הַכֵּלִים בְּלִי אוֹרוֹת, וְהָאוֹרוֹת בְּלִי כֵלִים, כִּי הָאֱמוּנָה הוּא בְּחִינַת כֵּלִים, וְהַדַּעַת הוּא בְּחִינַת אוֹרוֹת, וּמֵחֲמַת זֶה נִתְבַּטֵּל הָאוֹר לְגַמְרֵי, כִּי חוֹזֵר הַכֹּל אֶל אֵין־סוֹף מֵחֲמַת שֶׁהוּא בְּלֹא כְלִי וְהַכֵּלִים נָפְלוּ לְמַטָּה וְכוּ', כְּיָדוּעַ בִּכְתָבִים. הַיְנוּ שֶׁמֵּחֲמַת שֶׁרוֹדֵף שִׂכְלוֹ לְהִסְתַּכֵּל בְּמַה שֶּׁאֵין לוֹ רְשׁוּת, וְאֵינוֹ רוֹצֶה לִסְמֹךְ שָׁם עַל הָאֱמוּנָה לְבַד, נִמְצָא שֶׁפּוֹגֵם בְּהָאֱמוּנָה, וְאָז מֵחֲמַת רִבּוּי אוֹר הַשֵּׂכֶל נִשְׁבָּר כְּלִי הָאֱמוּנָה, וְאָז נִפְגָּם וְנוֹפֵל הָאֱמוּנָה, וְאָז נִתְבַּטֵּל הַדַּעַת לְגַמְרֵי, שֶׁאֵינוֹ יָכוֹל עַל־יְדֵי־זֶה לְהָבִין וּלְהַשִּׂיג אֲפִלּוּ מַה שֶּׁהָיָה אֶפְשָׁר לוֹ לְהָבִין בַּתְּחִלָּה, כִּי חָזַר הַכֹּל אֶל בְּחִינַת הָאֵין־סוֹף מֵאַחַר שֶׁנִּשְׁבַּר הַכְּלִי וְהַצִּמְצוּמִים שֶׁהוּא הָאֱמוּנָה הַקְּדוֹשָׁה. וְזֶה בְּחִינַת חֵטְא עֵץ־ הַדַּעַת, שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, דְּאִסְתַּכַּל בְּמָה דְּלָא הֲוָה לֵהּ רְשׁוּת, שֶׁעַל יְדֵי־זֶה חָזַר וְגָרַם שְׁבִירַת כֵּלִים כַּמּוּבָא (שם אותיות ג ד). 
צג. כְּלַל הַדָּבָר, שֶׁהָעִקָּר הוּא הָאֱמוּנָה בִּפְשִׁיטוּת, לְהַאֲמִין בְּהַשֵּׁם יִתְבָּרַךְ בִּתְמִימוּת וּבִפְשִׁיטוּת בְּלִי שׁוּם חֲקִירוֹת וְחָכְמוֹת כְּלָל, וּכְשֶׁזּוֹכֶה לִהְיוֹת חָזָק בָּזֶה יָמִים וְשָׁנִים הַרְבֵּה, אֲזַי אִם יִזְכֶּה, יַחְמֹל עָלָיו הַשֵּׁם יִתְבָּרַךְ וְיִפְתַּח לוֹ שְׁבִילֵי הַשֵּׂכֶל וְיוּכַל לְהַשִּׂיג וּלְהָבִין מְעַט בִּידִיעָתוֹ יִתְבָּרַךְ. וַאֲפִלּוּ אַחַר־כָּךְ, כְּשֶׁיִּזְכֶּה לְאֵיזֶה יְדִיעָה וְהַשָּׂגָה, הוּא צָרִיךְ לִתֵּן גְּבוּל לְדַעְתּוֹ שֶׁלֹּא יִסְתַּכֵּל בְּמַה שֶּׁאֵין לוֹ רְשׁוּת, כִּי בַּמֻּפְלָא מִמְּךָ אַל תִּדְרשׁ, רַק לִסְמֹךְ עַל אֱמוּנָה לְבַד, כִּי לְעוֹלָם צְרִיכִין לְהִתְחַזֵּק רַק בֶּאֱמוּנָה, שֶׁהִיא הַיְסוֹד וְהַקִּיּוּם שֶׁל כָּל הָעוֹלָמוֹת, וְהָאֱמוּנָה הוּא בְּרֹאשׁ וּבְסוֹף וּבְאֶמְצַע, בִּבְחִינַת "אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבַּלְעָדַי אֵין אֱלֹקִים" - "אֲנִי" הוּא בְּחִינַת מַלְכוּת אֱמוּנָה כַּיָּדוּעַ, וּמִבַּלְעֲדֵי הָאֱמוּנָה אִי אֶפְשָׁר לָדַעַת מֵהַשֵּׁם יִתְבָּרַךְ, בְּחִינַת "וּמִבַּלְעָדַי אֵין אֱלֹקִים" (שם

). 
צה. אַף־עַל־פִּי שֶׁזֶּה הַדְּבֵקוּת הַנַּ"ל יָקָר מְאֹד, אַף־עַל־פִּי־כֵן אִי אֶפְשָׁר לִהְיוֹת דָּבוּק תָּמִיד, כִּי אִי אֶפְשָׁר שֶׁהָאֱמוּנָה הַקְּדוֹשָׁה תְּקַבֵּל תָּמִיד מִן הַדַּעַת הַקְּדוֹשָׁה, כְּדֵי שֶׁלֹּא יִתְגַּבְּרוּ, חַס וְשָׁלוֹם, הָעֲנָנִין דִּמְכַסָּיִין עַל עַיְנִין, שֶׁהֵם בְּחִינַת קְלִפַּת עֵשָׂו וְיִשְׁמָעֵאל, שֶׁהֵם הַקְּלִפּוֹת וְהַכְּפִירוֹת הַבָּאִים מִבְּחִינַת שְׁבִירַת כֵּלִים הַנַּ"ל. כִּי בְּכָל עֵת שֶׁצְּרִיכִין לַעֲשׂוֹת אֵיזֶה יִחוּד דִּקְדֻשָּׁה שֶׁהוּא בְּחִינַת דְּבֵקוּת כַּנַּ"ל, אָז צְרִיכִין לְעוֹרֵר תְּחִלַּת הַצִּמְצוּם הַנַּ"ל וּלְבָרֵר בֵּרוּרִים מִבְּחִינַת שִׁבְרֵי־כֵלִים (עַיֵּן פְּנִים); וּמֵחֲמַת שֶׁבְּאֵלּוּ הַשִּׁבְרֵי־כֵלִים נֶאֱחָז הַסִּטְרָא־אָחֳרָא וְהַקְּלִפּוֹת מְאֹד מְאֹד, עַל־כֵּן צְרִיכִין לִהְיוֹת אִישׁ־חַיִל וְגִבּוֹר גָּדוֹל מִי שֶׁרוֹצֶה לַעֲסֹק בָּזֶה לְיַחֵד יִחוּדִים וּלְזַוֵּג הַמִּדּוֹת הַקְּדוֹשִׁים, כְּדֵי שֶׁלֹּא יִתְגָּרוּ בּוֹ הַכְּפִירוֹת שֶׁהֵם הַקְּלִפּוֹת שֶׁנֶּאֱחָזִין בְּשִׁבְרֵי־כֵלִים, וְהֵם הֵם בְּחִינַת הָעֲנָנִין דִּמְכַסָּיִין עַל עַיְנִין, וּצְרִיכִין לְהִשָּׁמֵר מֵהֶם מְאֹד. וַאֲפִלּוּ מִי שֶׁהוּא אִישׁ־חַיִל וְיוֹדֵעַ לְהִשָּׁמֵר מֵהֶם, אַף־עַל־פִּי־כֵן אִי אֶפְשָׁר לוֹ לִהְיוֹת דָּבוּק תָּמִיד, שֶׁלֹּא יִתְגַּבְּרוּ, חַס וְשָׁלוֹם, הַכְּפִירוֹת וְהַקְּלִפּוֹת הַנֶּאֱחָזִין בְּשִׁבְרֵי־כֵלִים שֶׁעוֹסְקִין לְבָרֵר אוֹתָם עַל־יְדֵי הַדְּבֵקוּת וְהַיִּחוּד. וְעַל־כֵּן גַּם הַצַּדִּיק צָרִיךְ לְבַטֵּל עַצְמוֹ לִפְעָמִים מִדְבֵקוּתוֹ, בִּבְחִינַת 'בִּטּוּלָהּ שֶׁל תּוֹרָה זֶהוּ קִיּוּמָהּ', עַד שֶׁיָּבוֹא מָשִׁיחַ וִיתַקֵּן הָעוֹלָם בִּשְׁלֵמוּת וְיִתְבַּטְּלוּ כָּל הַקְּלִפּוֹת וְהָעֲנָנִין דִּמְכַסָּיִין עַל עַיְנִין הַנַּ"ל, וְאָז יִהְיוּ יְכוֹלִים לִהְיוֹת דְּבוּקִים בְּהַשֵּׁם יִתְבָּרַךְ בִּתְמִידוּת (שם אותיות ו, ט). 
צו. אִי אֶפְשָׁר לְהַמְשִׁיךְ הַדַּעַת לְתוֹךְ הָאֱמוּנָה, כִּי־אִם כְּשֶׁהָאֱמוּנָה טְהוֹרָה וּקְדוֹשָׁה, שֶׁאָז יֶשׁ לָהּ כֹּחַ לְקַבֵּל אוֹר הַדַּעַת וּלְהוֹלִיד וּלְגַלּוֹת עַל־יְדֵי־זֶה הוֹלָדוֹת וְהִתְגַּלּוּת קְדוֹשׁוֹת; אֲבָל תֵּכֶף כְּשֶׁמִּתְעוֹרֵר דַּם־נִדּוּת בְּהָאִשָּׁה יִרְאַת־הַשֵּׁם, כִּבְיָכוֹל, דְּהַיְנוּ כְּשֶׁמַּתְחִילִין לְבַלְבֵּל אֶת אֱמוּנָתוֹ בְּקֻשְׁיוֹת וּכְפִירוֹת הַנִּמְשָׁכִין מִשְּׁבִירַת כֵּלִים, שֶׁזֶּה בְּחִינַת דַּם־נִדּוּת, כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל: עֲבוֹדָה זָרָה מְטַמְּאָה כְּנִדָּה, אֲזַי אָסוּר לוֹ לְהִשְׁתַּדֵּל לְהַמְשִׁיךְ הַדַּעַת לְתוֹךְ הָאֱמוּנָה, כִּי אָז צָרִיךְ לֵישֵׁב בָּדָד וְלִבְרֹחַ מִן הַדַּעַת לְגַמְרֵי, דְּהַיְנוּ שֶׁלֹּא יִשְׁתַּמֵּשׁ עִם הַדַּעַת כְּלָל וְלֹא יְחַבֵּר אָז אֶת הַדַּעַת עִם הָאֱמוּנָה כְּלָל, דְּהַיְנוּ שֶׁלֹּא יִרְצֶה לְהַמְשִׁיךְ הַדַּעַת לְהָבִין וּלְתָרֵץ הַקֻּשְׁיוֹת וְהַחֲקִירוֹת וְהַכְּפִירוֹת הָעוֹלִים עַל מֹחוֹ, כִּי תֵּכֶף כְּשֶׁעוֹלִים עַל דַּעְתּוֹ קֻשְׁיוֹת וּכְפִירוֹת, חַס וְשָׁלוֹם, אֲזַי הוּא צָרִיךְ לִסְמֹךְ רַק עַל הָאֱמוּנָה לְבַד בְּלִי שׁוּם הֲבָנַת הַדַּעַת, כִּי כְּשֶׁיִּרְצֶה אָז לְהָבִין בְּשֵׂכֶל, אֲזַי יִתְגַּבְּרוּ הַקֻּשְׁיוֹת וְהַכְּפִירוֹת, שֶׁהֵם בְּחִינַת דַּם־נִדּוּת, עַל הַשֵּׂכֶל, וְלֹא דַי שֶׁלֹּא יְתַקֵּן אֶת הָאֱמוּנָה עַל־יְדֵי הַשֵּׂכֶל, אַדְּרַבָּה, הָאֱמוּנָה וְהַשֵּׂכֶל יִהְיוּ נִפְגָּמִין וְנִתְקַלְקְלִין יוֹתֵר עַל־יְדֵי־זֶה, בִּבְחִינַת "וּתְהִי נִדָּתָהּ עָלָיו", וְיִתְבַּטֵּל הַשֵּׂכֶל וְהָאֱמוּנָה לְגַמְרֵי וְיָכוֹל לָבוֹא עַל־יְדֵי־זֶה לִכְפִירוֹת גְּמוּרוֹת, רַחֲמָנָא לִצְּלַן. וְזֶה בְּחִינַת חֹמֶר אִסּוּר נִדָּה, כִּי אִישׁ וְאִשָּׁה בְּשָׁרְשָׁן הֵם בְּחִינַת דַּעַת וֶאֱמוּנָה, וּכְשֶׁמִּתְעוֹרֵר הַדַּם־נִדּוּת, חַס וְשָׁלוֹם, שֶׁהֵם בְּחִינַת הַכְּפִירוֹת, אָז נֶאֱמָר: "וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ, לֹא תִקְרַב", שֶׁלֹּא יִתְגַבֵּר הַדַּם־נִדּוּת, חַס וְשָׁלוֹם, עַל הַדַּעַת הַקְּדוֹשָׁה וְיִתְבַּטֵּל הַדַּעַת וְהָאֱמוּנָה לְגַמְרֵי וְיִתְגַּבְּרוּ הַכְּפִירוֹת, חַס וְשָׁלוֹם. וְאָז עִקַּר הַתִּקּוּן, שֶׁיִּהְיֶה פֵּרוּד בֵּין הַדַּעַת וְהָאֱמוּנָה, וְאָז צְרִיכִין לְסַלֵּק הַדַּעַת לְגַמְרֵי וְלִסְמֹךְ רַק עַל אֱמוּנָה לְבָד. וְזֶה: "וְהִזַּרְתֶּם אֶת בְּנֵי־יִשְׂרָאֵל", וְאָמְרוּ רַבּוֹתֵינוּ זַ"ל, שֶׁצְּרִיכִין לִפְרשׁ סָמוּךְ לְוִסְתָּהּ, כִּי לָא מִבַּעְיָא בְּעֵת נִדּוּתָהּ צְרִיכִין לִפְרשׁ, אֶלָּא אֲפִלּוּ סָמוּךְ לְוִסְתָּהּ, הַיְנוּ תֵּכֶף כְּשֶׁיּוֹדְעִין שֶׁיַּתְחִילוּ לַעֲלוֹת עַל הַדַּעַת אֵיזֶה קֻשְׁיוֹת וּכְפִירוֹת שֶׁהֵם בְּחִינַת דַּם־נִדּוּת, אֲזַי תֵּכֶף צְרִיכִין לְהַפְרִישׁ אֶת הַדַּעַת לִבְלִי לְהִשְׁתַּמֵּשׁ עִמּוֹ כְּלָל, רַק לִסְמֹךְ עַל אֱמוּנָה לְבָד. וְהַכְּלָל, שֶׁאָסוּר לְהִשְׁתַּמֵּשׁ עִם דַּעְתּוֹ כִּי־אִם בְּעֵת שֶׁהָאֱמוּנָה עַל מְכוֹנָהּ, שֶׁהָאֱמוּנָה חֲזָקָה וּנְכוֹנָה אֶצְלוֹ בְּתֹקֶף גָּדוֹל וְאֵין לוֹ שׁוּם סָפֵק וְקֻשְׁיָא כְּלָל. וְאָז כְּשֶׁהָאֱמוּנָה חֲזָקָה וּנְכוֹנָה אֶצְלוֹ בֶּאֱמֶת בִּתְמִימוּת וּבִפְשִׁיטוּת בְּתֹקֶף גָּדוֹל, אָז יֶשׁ לוֹ רְשׁוּת לִרְדֹּף וּלְהִשְׁתּוֹקֵק לְהַשִּׂיג וְלֵידַע מְעַט מִמֶּנּוּ יִתְבָּרַךְ כְּפִי מַדְרֵגָתוֹ, כִּי לְכָךְ נוֹצַר, בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ; אֲבָל תֵּכֶף כְּשֶׁמַּתְחִילִין לִכְנֹס בּוֹ אֵיזֶה קֻשְׁיוֹת וַחֲקִירוֹת, שֶׁזֶּהוּ בְּחִינַת דַּםשׂנִדּוֹת, אָז צָרִיךְ לִבְרֹחַ מִן הַשֵּׂכֶל לְגַמְרֵי וְלִבְלִי לְהִשְׁתַּמֵּשׁ עִם הַשֵּׂכֶל כְּלָל, רַק לִסְמֹךְ עַל אֱמוּנָה לְבָד (שם אותיות ז ח, ועיין שם

). 
צח. עִקַּר הַבְּרִיאָה הָיְתָה בִּשְׁבִיל הָאָדָם, דְּהַיְנוּ בִּשְׁבִיל הַצַּדִּיק שֶׁנִּקְרָא אָדָם. וְעִקַּר מַעֲלַת הָאָדָם הוּא, שֶׁיֶּשׁ לוֹ כֹּחַ לְקַשֵּׁר וּלְחַבֵּר כָּל הָעוֹלָמוֹת יַחַד, דְּהַיְנוּ לְחַבֵּר עָלְמָא תַתָּאָה בְּעָלְמָא עִלָּאָה, שֶׁבָּהֶם כְּלוּלִים תִּקּוּן כָּל הָעוֹלָמוֹת, כִּי הָאָדָם כָּלוּל מִשְּׁנֵיהֶם, מֵעֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, כִּי זֶה עִקַּר הַשְּׁלֵמוּת וְזֶה עִקַּר הַשַּׁעֲשׁוּעִים שֶׁל הַשֵּׁם יִתְבָּרַךְ כְּשֶׁמִּתְחַבֵּר וּמִתְקַשֵּׁר עוֹלָם הַתַּחְתּוֹן, שֶׁהוּא עוֹלָם הָעֲשִׂיָּה הַגַּשְׁמִי הַזֶּה, בָּעוֹלָמוֹת הָעֶלְיוֹנִים הָרוּחָנִיִּים וְהַזַּכִּים מְאֹד, בִּבְחִינַת "וְאָבִיתָ תְהִלָּה מִגּוּשֵׁי עָפָר, מִקְּרוּצֵי חֹמֶר", כִּי זֶהוּ רְצוֹנוֹ יִתְבָּרַךְ שֶׁבִּשְׁבִיל זֶה בָּרָא כָּל הַבְּרִיאָה מֵרֹאשׁ וְעַד סוֹף, וְהַכֹּל בִּשְׁבִיל הָאָדָם הַבַּעַל־בְּחִירָה שֶׁהוּא בָּעוֹלָם הַזֶּה הַגַּשְׁמִי, שֶׁעִקַּר עֲבוֹדָתוֹ הוּא לְקַשֵּׁר תַּחְתּוֹנִים בְּעֶלְיוֹנִים, שֶׁזֶּה עִקַּר תַּעֲנוּגָיו וְשַׁעֲשׁוּעָיו יִתְבָּרַךְ, כִּי מִיּוֹם שֶׁבָּרָא הַקָּדוֹשׁ־בָּרוּךְ־הוּא אֶת הָעוֹלָם נִתְאַוָּה לִהְיוֹת דִּירָתוֹ בַּתַּחְתּוֹנִים כְּמַאֲמַר רַבּוֹתֵינוּ זַ"ל, וְעִקַּר הִתְקַשְּׁרוּת וְהִכָּלְלוּת שֶׁל תַּחְתּוֹנִים בְּעֶלְיוֹנִים, עָלְמָא תַתָּאָה בְּעָלְמָא עִלָּאָה, הוּא רַק עַל־יְדֵי אֱמוּנָה שֶׁהוּא כְּלַל הַתּוֹרָה, בִּבְחִינַת "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", כִּי כָּל מִצְו?ֹת הַתּוֹרָה הֵם בָּעוֹלָם הַזֶּה בְּעוֹלַם הַמַּעֲשֶׂה דַּיְקָא, וְרֻבָּם כְּכֻלָּם מְלֻבָּשִׁין בִּדְבָרִים גַּשְׁמִיִּים, שֶׁצְּרִיכִין לַעֲשׂוֹת צִיצִת מִצֶּמֶר וּפִשְׁתָּן דַּיְקָא, וּתְפִלִּין מֵעוֹר בְּהֵמָה וְכֵן סֻכָּה וְלוּלָב וְכוּ', וְעַל־יְדֵי שֶׁאָנוּ מְקַיְּמִין מִצְו?ֹתָיו יִתְבָּרַךְ בְּמַעֲשֶׂה דַּיְקָא, בִּדְבָרִים גַּשְׁמִיִּים, עַל־יְדֵי־זֶה נַעֲשֶׂה עִקַּר הַיִּחוּד וְהַהִתְקַשְּׁרוּת שֶׁל עָלְמָא תַתָּאָה בְּעָלְמָא עִלָּאָה, שֶׁנִּכְלָל שְׁכִינַת עֻזּוֹ הַשּׁוֹכֵן בַּתַּחְתּוֹנִים בְּמִי שֶׁהוּא מְרוֹמָם עַל כָּל בְּרָכָה וּתְהִלָּה, כִּי הוּא יִתְבָּרַךְ לְמַעְלָה מִכָּל הָרוּחָנִיּוּת וּמִכָּל הַשֵּׁמוֹת וּמִכָּל הַמַּחֲשָׁבוֹת, וְלֵית מַחֲשָׁבָה תְּפִיסָא בֵּהּ כְּלָל. וְעַל־כֵּן בֶּאֱמֶת, זֹאת הַבְּחִינָה אִי אֶפְשָׁר לְהַשִּׂיג עַל־יְדֵי שׁוּם שֵׂכֶל וְחָכְמָה אֵיךְ אֶפְשָׁר לְקַשֵּׁר עוֹלָם הַגַּשְׁמִי הַזֶּה בְּבוֹרֵא הַכֹּל יִתְבָּרַךְ שֶׁהוּא מְרוֹמָם מִכָּל הָרוּחָנִיּוּת, וְאֵיךְ שַׁיָּךְ שֶׁהוּא יִתְבָּרַךְ יְקַבֵּל תַּעֲנוּג וְשַׁעֲשׁוּעַ מִמַּעֲשֵׂה הַתַּחְתּוֹנִים, אֲשֶׁר עַל־יְדֵי מְבוּכָה זֹאת רַבִּים נִתְפַּקְּרוּ לְגַמְרֵי, רַחֲמָנָא לִצְּלַן, וְרַבִּים אוֹמְרִים עַל הַמִּצְו?ֹת טְעָמִים שֶׁל שְׁטוּת וָהֶבֶל; אֲבָל בֶּאֱמֶת אִי אֶפְשָׁר לְהַשִּׂיג וּלְהָבִין זֹאת בְּשׁוּם שֵׂכֶל, כִּי־אִם בֶּאֱמוּנָה לְבַד, כְּמוֹ שֶׁנֶּאֱמַר: "כָּל מִצְו?ֹתֶיךָ אֱמוּנָה", וְהָאֱמוּנָה הַזֹּאת מַשְׁפִּיעִים בָּנוּ הַצַּדִּיקִים הָאֲמִתִּיִּים שֶׁזָּכוּ לְ'תַכְלִית הַיְדִיעָה - אֲשֶׁר לֹא נֵדַע', וּמֵאַחַר שֶׁהֵם בִּבְחִינַת 'לֹא נֵדַע', שֶׁזֶּהוּ תַּכְלִית הַיְדִיעָה, עַל־כֵּן הֵם בְּתַכְלִית שְׁלֵמוּת הָאֱמוּנָה, כִּי הָאֱמוּנָה הוּא בְּמַה שֶּׁאֵין מְבִינִים. וְעַל־יְדֵי אֱמוּנָה הַזֹּאת, שֶׁהוּא יְסוֹד כָּל הַתּוֹרָה וְהַמִּצְו?ֹת, עַל־יְדֵי־זֶה מִתְקַשְּׁרִין וְנִכְלָלִין כָּל הָעוֹלָמוֹת קט הַתַּחְתּוֹנִים בָּעֶלְיוֹנִים, שֶׁזֶּהוּ עִקַּר הַתַּכְלִית שֶׁבִּשְׁבִיל זֶה נִבְרָא הַכֹּל כַּנַּ"ל (הל' נדרים הל' ד, אותיות יב יג יד). 
צט. הַצַּדִּיק הַגָּדוֹל בְּמַעֲלָה, כָּל מַה שֶּׁבָּא לְאֵיזֶה הַשָּׂגָה וּמַדְרֵגָה, אֲפִלּוּ כְּשֶׁזּוֹכֶה לַעֲלִיָּה גְדוֹלָה, הוּא מֵשִׂים עַצְמוֹ תֵּכֶף כְּאֵינוֹ יוֹדֵעַ, וְחוֹזֵר בְּכָל פַּעַם אֶל הָאֱמוּנָה; כִּי הוּא יוֹדֵעַ וּמַאֲמִין, שֶׁכְּפִי גְּדֻלַּת הַשֵּׁם יִתְבָּרַךְ, עֲדַיִן אֵינוֹ יוֹדֵעַ כְּלָל, כִּי גָּבֹהַּ מֵעַל גָּבֹהַּ שֹׁמֵר וְכוּ', כִּי לִגְדֻלָּתוֹ אֵין חֵקֶר, וְעַל־כֵּן אַף־עַל־פִּי שֶׁזּוֹכֶה לְהַשָּׂגָה גְּבוֹהָה וַעֲצוּמָה מְאֹד, אַף־עַל־פִּי־כֵן אֵינוֹ סוֹמֵךְ אֶת עַצְמוֹ עַל זֶה לַעֲבֹד אֶת הַשֵּׁם יִתְבָּרַךְ בְּחָכְמוֹת לְבַד, רַק הוּא חוֹזֵר בְּכָל פַּעַם לַעֲבֹד אֶת הַשֵּׁם יִתְבָּרַךְ בִּתְמִימוּת בַּעֲבוֹדוֹת פְּשׁוּטוֹת, וּמוֹרִיד אֶת עַצְמוֹ לְכָל הַמַּדְרֵגוֹת הַתַּחְתּוֹנוֹת, לְהַעֲלוֹת נַחַת־רוּחַ לְפָנָיו יִתְבָּרַךְ מִכֻּלָּם, כִּי זֶה עִקַּר שַׁעֲשׁוּעָיו יִתְבָּרַךְ, וְעַל־ יְדֵי־זֶה בְּעַצְמוֹ זוֹכֶה הַצַּדִּיק לַעֲלִיּוֹת גְּבוֹהוֹת יוֹתֵר וְיוֹתֵר, כִּי עַל־יְדֵי אֱמוּנָה וּתְמִימוּת כַּנַּ"ל, זוֹכִין לַעֲלוֹת עַל כָּל הַמַּדְרֵגוֹת וּלְהַגִּיעַ לִבְחִינַת רָצוֹן וְכוּ' שֶׁעוֹלֶה עַל הַכֹּל (שם

). 
קא. עִקַּר שְׁלֵמוּת הִתְגַּלּוּת הָאֱמֶת הוּא בַּסּוֹף, בִּבְחִינַת "טוֹב אַחֲרִית דָּבָר מֵרֵאשִׁיתוֹ", בִּבְחִינַת "שְׂפַת אֱמֶת תִּכּוֹן לָעַד" - "כּוֹנַנְתָּ" לֹא כְתִיב אֶלָּא "תִּכּוֹן", שֶׁבַּסּוֹף לֶעָתִיד יִתְגַּלֶּה הָאֱמֶת, כִּי בְּרֵאשִׁית הַדָּבָר אִי אֶפְשָׁר לְגַלּוֹת הָאֱמֶת בְּשׁוּם אֹפֶן, כִּי אָז תִּתְבַּטֵּל הַבְּחִירָה. כִּי אִם הָיָה הָאָדָם רוֹאֶה בְּעֵינָיו תַּעֲנוּגֵי הָעוֹלָם הַבָּא מַה שֶּׁיִּזְכֶּה עַל־יְדֵי עֲזִיבַת הָעֲבֵרָה וְהַתַּאֲוָה וְכֵן עַל־יְדֵי עֲשִׂיַּת הַמִּצְוָה, בְּוַדַּאי הָיָה הַכֹּל בּוֹרְחִים מִן הָעֲבֵרָה וְרוֹדְפִים אַחֲרֵי הַמִּצְו?ֹת בְּלִי שׁוּם בְּחִירָה כְּלָל; אַךְ עִקַּר הַבְּחִירָה הוּא מֵחֲמַת שֶׁאֵין רוֹאִים הָאֱמֶת בִּתְחִלָּתוֹ, אַדְּרַבָּא, כְּפִי פַּשְׁטוּת קַטְנוּת דַּעַת הָאָדָם, נִדְמֶה לוֹ בֶּאֱמֶת שֶׁאֲכִילָה וּשְׁתִיָּה וּשְׁאָר תַּאֲווֹת הַגּוּף הֵם תַּעֲנוּג, וַעֲבוֹדַת־הַשֵּׁם הוּא יְגִיעָה, וְזֶה עִקַּר נִסְיוֹנוֹ, שֶׁצָּרִיךְ לִסְבֹּל יְגִיעוֹת גְּדוֹלוֹת בִּשְׁבִיל עֲבוֹדַת־הַשֵּׁם, וְכָל זֶה מֵחֲמַת שֶׁאֵין רוֹאֶה הָאֱמֶת תֵּכֶף, וְעַל־ יְדֵי־זֶה דַּיְקָא יִזְכֶּה לְבַסּוֹף לְקַבֵּל שָׂכָר טוֹב שֶׁהוּא הִתְגַּלּוּת הָאֱמֶת לַאֲמִתּוֹ שֶׁיִּתְגַּלֶּה לֶעָתִיד, שֶׁזֶּה עִקַּר קִבּוּל הַשָּׂכָר, וּלְפֻם צַעֲרָא אַגְרָא. וְכֵן כָּל הַקֻּשְׁיוֹת שֶׁקָּשֶׁה לְהָאָדָם עַל הַנְהָגַת הַשֵּׁם יִתְבָּרַךְ, וְכֵן מַה שֶּׁקָּשֶׁה עַל הַצַּדִּיקֵי־אֱמֶת, בִּפְרָט הַקֻּשְׁיוֹת שֶׁל הַחֲכָמִים בְּעֵינֵיהֶם וְשֶׁל הַמְחַקְּרִים, וְכָל זֶה מֵחֲמַת שֶׁלְּפִי הָאֱמֶת שֶׁבְּדַעְתָּם נִדְמֶה לָהֶם שֶׁרָאוּי שֶׁלֹּא לְהִתְנַהֵג כָּךְ, כִּי רוֹצֶה לְהָבִין וּלְהַשִּׂיג אֲמִתַּת הָאֱמֶת תֵּכֶף, אֲבָל אִישׁ־בַּעַר לֹא יֵדָע שֶׁאִי אֶפְשָׁר לְהַשִּׂיג וּלְהָבִין בַּשֵּׂכֶל אֲמִתָּתוֹ וְהַנְהָגָתוֹ יִתְבָּרַךְ בִּשְׁלֵמוּת, כִּי־אִם עַל־יְדֵי אֱמוּנָה כְּשֶׁמִּתְחַבֶּרֶת עִם הָאֱמֶת, וְלֶאֱמוּנָה זוֹכִין עַל־יְדֵי אֱמֶת, הַיְנוּ אִם יִרְצֶה לְהִסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ יָבִין שֶׁאִי אֶפְשָׁר עֲדַיִן לְהַשִּׂיג בִּשְׁלֵמוּת עֶצֶם אֲמִתַּת הָאֱמֶת, אַךְ אַף־עַל־פִּי־כֵן הָאֱמֶת הוּא כָּךְ, עַל־כֵּן צְרִיכִין לְהִתְחַזֵּק בֶּאֱמוּנָה לְהַאֲמִין בֶּהָאֱמֶת, כִּי כָּל הַקֻּשְׁיוֹת שֶׁקָּשִׁין לְהָאָדָם עַל הַנְהָגַת הַשֵּׁם יִתְבָּרַךְ, וְכֵן הָעַקְמִימִיּוּת שֶׁיֵּשׁ בְּלִבּוֹ עַל הַצַּדִּיקֵי־אֱמֶת, כָּל זֶה הוּא מֵחֲמַת שֶׁהוּא מְשֻׁקָּע בְּתַאֲוַת עוֹלָם הַזֶּה וַהֲבָלָיו וּבְכָבוֹד וְנִצָּחוֹן. וְעַל־כֵּן מִי שֶׁחָס עַל חַיָּיו בֶּאֱמֶת וְרוֹצֶה לִזְכּוֹת לְחַיִּים נִצְחִיִּים וּמַחֲזִיר פָּנָיו קְצָת מִתַּאֲוַת עוֹלָם הַזֶּה וַהֲבָלָיו וְחוֹשֵׁב עַל תַּכְלִיתוֹ הַנִּצְחִי, אֲזַי הַשֵּׁם יִתְבָּרַךְ מְרַחֵם עָלָיו וּמֵאִיר לוֹ דַּרְכֵי הָאֱמוּנָה בְּאֹפֶן שֶׁיִּהְיֶה לוֹ כֹּחַ לִבְחֹר בְּהָאֱמֶת וֶאֱמוּנָה אִם יִרְצֶה. וְאָז הוּא מֵבִין שֶׁכָּל הַנִּסְיוֹנוֹת וְהָעַקְמִימִיּוּת וְהַקֻּשְׁיוֹת שֶׁרוֹצִים לְהַסְתִּיר וּלְהַעְלִים מִמֶּנּוּ אוֹר הָאֱמֶת, כָּל זֶה הוּא רַק מֵחֲמַת שֶׁהַשֵּׁם יִתְבָּרַךְ אֵינוֹ מְגַלֶּה הָאֱמֶת בַּתְּחִלָּה בִּשְׁלֵמוּת כְּדֵי שֶׁיִּהְיֶה בְּחִירָה, רַק מֵאִיר הָאֱמֶת קְצָת בְּאֹפֶן שֶׁיִּהְיֶה כֹּחַ לְהַאֲמִין לְמִי שֶׁיִּרְצֶה לְהִסְתַּכֵּל עַל הָאֱמֶת לַאֲמִתּוֹ. וּמִבְּחִינָה זוֹ הָיָה כָּל הַנִּסְיוֹנוֹת שֶׁעָבְרוּ עַל אֲבוֹתֵינוּ בַּמִּדְבָּר, וְכֵן הוּא בְּכָל דּוֹר וּבְכָל זְמַן, וְעִקַּר הַגְּאֻלָּה תָּלוּי בָּזֶה; כִּי כָּךְ דֶּרֶךְ הַשֵּׁם יִתְבָּרַךְ, שֶׁהוּא עוֹסֵק בְּרַחֲמָיו לְקָרֵב אֶת הָאָדָם בְּכַמָּה דְּרָכִים, אַךְ אַף־עַל־פִּי־כֵן הוּא מַנִּיחַ לוֹ מָקוֹם לְהִסְתַּפֵּק קְצָת בִּשְׁבִיל נִסָּיוֹן וּבְחִירָה, וּכְשֶׁמִּתְחַזֵּק בֶּאֱמוּנָה שְׁלֵמָה עַל־ יְדֵי שֶׁמִּסְתַּכֵּל עַל הָאֱמֶת, עַל כָּל הַחֲסָדִים שֶׁעָשָׂה עִמּוֹ הַשֵּׁם יִתְבָּרַךְ, וְכֵן לְעִנְיַן אֱמוּנַת חֲכָמִים, אִם יִסְתַּכֵּל בֶּאֱמֶת עַל כָּל הַהִתְגַּלּוּת וְהַנִּפְלָאוֹת שֶׁזָּכִינוּ עַל־יְדֵי הַצַּדִּיקֵי־אֱמֶת, עַל־יְדֵי־זֶה יִתְחַזֵּק בֶּאֱמוּנָה שְׁלֵמָה וְיָבִין שֶׁכָּל הָעַקְמִימִיּוּת וְהַמַּחֲלֹקֶת, הַכֹּל הוּא רַק בִּשְׁבִיל נִסָּיוֹן וּבְחִירָה, וְאִם יִתְחַזֵּק בֶּאֱמוּנָתוֹ אַחַר כָּל הָעַקְמִימִיּוּת וְהַמַּחֲלֹקֶת וְהַנִּסְיוֹנוֹת, אֲזַי עַל־יְדֵי־זֶה דַּיְקָא יִזְכֶּה לְכָל־טוּב (שם אותיות יב יג יד טו טז). 
קב. אֲפִלּוּ כְּשֶׁזּוֹכֶה הָאָדָם לְהִתְקָרֵב אֶל הָאֱמֶת עַל־יְדֵי תֹּקֶף אֱמוּנָתוֹ כַּנַּ"ל, צָרִיךְ גַּם־כֵּן שֶׁיִּהְיֶה לוֹ אֱמוּנָה בְּעַצְמוֹ, קיא שֶׁזֶּהוּ גַּם־כֵּן בִּכְלַל אֱמוּנַת חֲכָמִים, כַּמְבֹאָר בְּמָקוֹם אַחֵר. כִּי הַרְבֵּה מִתְרַחֲקִים עַל־יְדֵי רִבּוּי הַקֻּשְׁיוֹת שֶׁקָּשֶׁה לָהֶם עַל עַצְמָן, שֶׁרוֹאִים שֶׁזֶּה כַּמָּה שֶׁחוֹתְרִים וּמִתְיַגְּעִים בִּשְׁבִיל לְהַשִּׂיג הָאֱמֶת, וְאַף־עַל־פִּי־כֵן עֲדַיִן הֵם רְחוֹקִים כָּל־כָּךְ; וְכָל זֶה מַעֲשֵׂה הַבַּעַל־ דָּבָר שֶׁחוֹתֵר עֲלֵיהֶם לְרַחֲקָם יוֹתֵר, כִּי בֶּאֱמֶת אִי אֶפְשָׁר לְהָאָדָם בְּשׁוּם אֹפֶן שֶׁיֵּדַע בְּזֶה הָעוֹלָם הֵיכָן הוּא אוֹחֵז (וַאֲפִלּוּ דָּוִד הַמֶּלֶךְ, עָלָיו הַשָּׁלוֹם, אָמַר: יוֹדֵעַ אֲנִי שֶׁיֵּשׁ קִבּוּל שָׂכָר לַצַּדִּיקִים וְכוּ', אֲבָל אֵינִי יוֹדֵעַ אִם יֶשׁ לִי חֵלֶק עִמָּהֶם, כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל), וְזֶה מֵעִקְּרֵי הַנִּסְיוֹנוֹת שֶׁל הָאָדָם, שֶׁאֵינוֹ יוֹדֵעַ הֵיכָן הוּא עוֹמֵד וְאוֹחֵז, כִּי אִם הָיָה רוֹאֶה וְיוֹדֵעַ מַה שֶּׁזּוֹכֶה גַּם עַתָּה עַל־יְדֵי כָּל תְּנוּעָה וְהַעְתָּקָה שֶׁמְּנַתֵּק אֶת עַצְמוֹ מֵרַע לְטוֹב, אֲפִלּוּ תְּנוּעָה בְּעָלְמָא, אֲזַי בְּוַדַּאי הָיָה רָץ בְּכָל כֹּחוֹ לַעֲבוֹדַת־הַשֵּׁם וּלְתוֹרָתוֹ וְהָיָה מִתְבַּטֵּל הַבְּחִירָה לְגַמְרֵי, כִּי עִקַּר הַבְּחִירָה הוּא מַה שֶּׁאֵינוֹ רוֹאֶה וְיוֹדֵעַ מַה שֶּׁעוֹשֶׂה וּמְתַקֵּן כָּל אֶחָד לְפִי מְקוֹמוֹ וּשְׁעָתוֹ. עַל־כֵּן צְרִיכִין גַּם בָּזֶה לְהִתְחַזֵּק בֶּאֱמוּנָה, לֵידַע וּלְהַאֲמִין בְּדִבְרֵי רַבּוֹתֵינוּ זַ"ל, שֶׁאֵין שׁוּם תְּנוּעָה טוֹבָה נֶאֱבֶדֶת כְּלָל, כִּי לֵית רְעוּתָא טָבָא דְּאִתְאֲבִיד, וְסוֹף כָּל סוֹף לֹא יִשָּׁאֵר מִמֶּנּוּ רַק אֵיזֶה טוֹב שֶׁחָטַף בָּעוֹלָם הַזֶּה, וּבְוַדַּאי כָּל הַמַּרְבֶּה הֲרֵי זֶה מְשֻׁבָּח, אֲבָל אַף־עַל־פִּי־כֵן אַטּוּ מָאן דְּלָא יָכִיל לְמֶעְבַּד כֹּלָּא מִצְוָה - פַּלְגָּא מִצְוָה נָמֵי לָא לִעֲבַד?! וְכָל הַהִתְרַחֲקוּת שֶׁל בְּנֵי־אָדָם עַל־יְדֵי רַעְיוֹנִים וּמַחֲשָׁבוֹת כָּאֵלּוּ, הַכֹּל מֵחֲמַת בְּחִינָה הַנַּ"ל, הַיְנוּ מֵחֲמַת מַה שֶּׁרוֹצֶה לְהָבִין הָאֱמֶת תֵּכֶף וּמִיָּד. אֲבָל הַמַּאֲמִין לֹא יָחוּשׁ, וּצְרִיכִין לְהַמְתִּין הַרְבֵּה הַרְבֵּה עַד שֶׁיִּזְכֶּה לְהָבִין אֲמִתַּת דְּרָכָיו יִתְבָּרַךְ, כִּי יְשָׁרִים דַּרְכֵי ה' וְכוּ', כִּי עִקַּר הִתְגַּלּוּת הָאֱמֶת יִהְיֶה לְבַסּוֹף כַּנַּ"ל (שם

). 
קג. עִקַּר הַנְּקֻדָּה הַקְּדוֹשָׁה, שֶׁהוּא בְּחִינַת צַדִּיק, שֶׁיֵּשׁ בְּכָל אֶחָד מִיִּשְׂרָאֵל (שֶׁעַל־ יְדֵי אוֹר הַנְּקֻדָּה הַזֹּאת נִתְבַּטְּלִין כָּל הַחֲרָפוֹת וַאֲהָבוֹת רָעוֹת וְזוֹכִין לְאַהֲבָה דִּקְדֻשָּׁה), הוּא הָאֱמוּנָה הַקְּדוֹשָׁה שֶׁהִיא יְסוֹד הַכֹּל וְהִיא עִקַּר הַנְּקֻדָּה שֶׁל בְּחִינַת צַדִּיק, בְּחִינַת "וְצַדִּיק בֶּאֱמוּנָתוֹ יִחְיֶה". וְזֶה כָּל מִצְוַת קְרִיאַת־שְׁמַע; וּמֵחֲמַת שֶׁעִקַּר הִתְגַּלּוּת אוֹר הַנְּקֻדָּה הַקְּדוֹשָׁה הוּא עַל־יְדֵי דִּבּוּר־פֶּה דַּיְקָא, עַל־כֵּן צְרִיכִין לוֹמַר קְרִיאַת־שְׁמַע בְּפֶה מָלֵא דַּיְקָא. וְזֶהוּ שֶׁנִּסְמָךְ אַחַר "שְׁמַע יִשְׂרָאֵל", שֶׁהוּא עִקַּר אֱמוּנַת הַיִּחוּד, בְּחִינַת אוֹר הַנְּקֻדָּה הַקְּדוֹשָׁה, כְּתִיב תֵּכֶף אַחַר־כָּךְ "וְאָהַבְתָּ", כִּי עַל־יְדֵי־זֶה זוֹכִין לְאַהֲבָה דִּקְדֻשָּׁה. וְכֵן כָּל פָּרָשַׁת קְרִיאַת־שְׁמַע מְבֹאָר כָּל עִנְיַן הַמְשָׁכַת אוֹר הַנְּקֻדָּה הַקְּדוֹשָׁה, כַּמְבֹאָר בִּפְנִים (הל' מלמדים, הל' ד, אותיות ה, ח). 
קד. כָּל דִּבְרֵי הַצַּדִּיקִים וְהַחֲכָמִים הַנֶּאֱמָרִים בְּרוּחַ־הַקֹּדֶשׁ, בִּפְרָט בְּמַדְרֵגָה גְּבוֹהָה וְנִשְׂגָּבָה, הֵם סוֹבְלִים הַכֹּל, כָּל דִּבְרֵי אֱמֶת שֶׁמּוֹצְאִין בָּהֶם כָּל אֶחָד כְּפִי דַּעְתּוֹ (שם
